/// Result type for multi-table projection resolution
/// Contains: (columns_per_table, output_column_refs, schema, is_wildcard)
pub(crate) type MultiTableProjection = (Vec<Vec<usize>>, Vec<(usize, usize)>, ResultSchema, bool);
/// Outer column reference found in a correlated subquery (Phase 4B)
#[derive(Debug, Clone)]
struct OuterColumnRef {
    /// The table qualifier (alias or table name) the outer query used.
    ///
    /// Only the qualifier is needed: which column it names is resolved by
    /// NameCtx against the outer table, so recording it here would be a second
    /// copy of that lookup.
    qualifier: String,
}

/// A symbolic jump target.
///
/// Jump destinations used to be computed arithmetically, as offsets from
/// `program.len()` counting instructions that had not been emitted yet -- e.g.
/// `let skip_offset = if limit_reg.is_some() { 3 } else { 2 }`. That couples
/// every jump to the exact shape of the code after it, so inserting,
/// reordering, or conditionally omitting an instruction silently retargets the
/// jump. The failure mode is a wrong answer, not a crash.
///
/// A `Label` is created before it is known where it points, used as a jump
/// destination any number of times, and bound to an address later with
/// [`SqlCompiler::resolve`]. Unresolved labels are a compile-time bug and are
/// caught by an assertion when the program is finished.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Label(usize);

/// One FROM source visible to expression compilation.
pub(crate) struct Src<'t> {
    /// VM cursor id for this source.
    pub cursor: i64,
    /// Base register holding this source's columns, when the loop has already
    /// materialized them.
    ///
    /// Multi-table joins load every column into registers before evaluating
    /// join conditions, so a column reference there is a register offset
    /// rather than a `Column` read from a cursor. Modelling both here means
    /// one expression compiler serves both loop shapes.
    pub reg_base: Option<i64>,
    /// The table behind the cursor.
    pub table: &'t Table,
    /// How the query refers to it: the alias if there is one, else the table
    /// name. Stored ASCII-lowercased, since SQL identifiers are matched
    /// case-insensitively.
    pub refname: String,
}

/// A resolved column: where its value lives at run time.
#[derive(Clone, Copy, Debug)]
pub(crate) enum ColumnRef {
    /// Read column `col` from cursor `cursor`.
    Cursor { cursor: i64, col: usize },
    /// The value is already in this register.
    Register(i64),
}

impl ColumnRef {
    fn new(src: &Src<'_>, col: usize) -> Self {
        match src.reg_base {
            Some(base) => ColumnRef::Register(base + col as i64),
            None => ColumnRef::Cursor {
                cursor: src.cursor,
                col,
            },
        }
    }
}

/// Name resolution scope for [`SqlCompiler::code_expr`].
///
/// The reason two expression compilers drifted apart is that both threaded a
/// bare `(table, cursor_idx)` pair, a shape that cannot express a join, an
/// alias, or a post-aggregation scope. Everything a name can resolve against
/// lives here instead, so one compiler serves the SELECT list, WHERE, HAVING,
/// ORDER BY and SET clauses.
pub(crate) struct NameCtx<'t> {
    /// FROM sources in cursor order. Empty for `SELECT 1` (no FROM).
    pub srcs: Vec<Src<'t>>,

    /// Enclosing query's sources, for a correlated subquery.
    ///
    /// SQL resolves a name in the innermost scope first and only then looks
    /// outward, so these are consulted only when `srcs` has no match. Keeping
    /// them in a separate list rather than appending to `srcs` preserves that
    /// precedence, and keeps the ambiguity check meaningful: two tables in one
    /// FROM are ambiguous, but an inner name shadowing an outer one is not.
    pub outer: Vec<Src<'t>>,

    /// Aggregate results available to this expression, keyed by the rendered
    /// call text (`"sum(salary)"`).
    ///
    /// After aggregation an aggregate is a value like any other, so an
    /// expression may contain one -- `SUM(salary) + 1`. Binding them here lets
    /// the ordinary expression compiler handle the surrounding arithmetic
    /// instead of needing a separate post-aggregation compiler.
    pub agg_bindings: Vec<(String, i64)>,
}

impl<'t> NameCtx<'t> {
    /// The common single-table scope, equivalent to the old
    /// `(table, cursor_idx)` pair.
    pub(crate) fn single(table: &'t Table, cursor: i64) -> Self {
        NameCtx {
            srcs: vec![Src {
                cursor,
                reg_base: None,
                table,
                refname: table.name().to_ascii_lowercase(),
            }],
            outer: Vec::new(),
            agg_bindings: Vec::new(),
        }
    }

    /// A scope over several FROM sources, for joins.
    pub(crate) fn multi(srcs: Vec<Src<'t>>) -> Self {
        NameCtx {
            srcs,
            outer: Vec::new(),
            agg_bindings: Vec::new(),
        }
    }

    /// A scope with no FROM sources, for constant expressions.
    #[allow(dead_code)] // used by constant-expression contexts
    pub(crate) fn empty() -> Self {
        NameCtx {
            srcs: Vec::new(),
            outer: Vec::new(),
            agg_bindings: Vec::new(),
        }
    }

    /// Normalized key for an aggregate call, used to bind and to look up.
    pub(crate) fn agg_key(expr: &Expr) -> String {
        expr.to_string().to_ascii_lowercase()
    }

    /// Register holding the result of an already-computed aggregate.
    fn lookup_agg(&self, expr: &Expr) -> Option<i64> {
        let key = Self::agg_key(expr);
        self.agg_bindings
            .iter()
            .find(|(k, _)| *k == key)
            .map(|(_, r)| *r)
    }

    /// Resolve an unqualified column name across every source.
    ///
    /// Case-insensitive: `SELECT NAME` already worked while
    /// `WHERE NAME = 'x'` did not, because the projection path lowercased and
    /// `find_column_index` compared exactly.
    ///
    /// Returns `Err` if no source has the column, or if more than one does --
    /// silently picking the first would make the result depend on FROM order.
    fn resolve_unqualified(&self, name: &str) -> SqawkResult<ColumnRef> {
        let want = name.to_ascii_lowercase();
        let mut found: Option<ColumnRef> = None;
        for src in &self.srcs {
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    if found.is_some() {
                        return Err(SqawkError::InvalidSqlQuery(format!(
                            "Column '{}' is ambiguous across the tables in FROM",
                            name
                        )));
                    }
                    found = Some(ColumnRef::new(src, i));
                    break;
                }
            }
        }
        if let Some(col) = found {
            return Ok(col);
        }
        // Not in this scope: look outward, nearest first.
        for src in &self.outer {
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    return Ok(ColumnRef::new(src, i));
                }
            }
        }
        Err(SqawkError::ColumnNotFound(name.to_string()))
    }

    /// Resolve a `table.column` (or `alias.column`) reference.
    fn resolve_qualified(&self, qualifier: &str, name: &str) -> SqawkResult<ColumnRef> {
        let qual = qualifier.to_ascii_lowercase();
        let want = name.to_ascii_lowercase();
        for src in &self.srcs {
            if src.refname != qual {
                continue;
            }
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    return Ok(ColumnRef::new(src, i));
                }
            }
            return Err(SqawkError::ColumnNotFound(format!(
                "{}.{}",
                qualifier, name
            )));
        }
        // Qualifier not in this scope: try the enclosing one, which is how a
        // correlated subquery refers to its outer row.
        for src in &self.outer {
            if src.refname != qual {
                continue;
            }
            for (i, col) in src.table.column_metadata().iter().enumerate() {
                if col.name.to_ascii_lowercase() == want {
                    return Ok(ColumnRef::new(src, i));
                }
            }
        }
        // Unknown qualifier entirely: fall back to an unqualified match so a
        // single-table query can still say `employees.age` when the cursor was
        // opened under a different refname.
        self.resolve_unqualified(name)
    }
}

/// Classify a join operator for the inner-join rewrite.
///
/// `Some(Some(c))` = inner join with constraint `c`; `Some(None)` = cross join;
/// `None` = not rewritable (outer joins and the exotic forms).
fn classify_join_for_rewrite(op: &sqlparser::ast::JoinOperator) -> Option<Option<&JoinConstraint>> {
    use sqlparser::ast::JoinOperator as J;
    match op {
        J::Join(c) | J::Inner(c) => Some(Some(c)),
        J::CrossJoin(_) => Some(None),
        _ => None,
    }
}

/// SQL statement compiler that generates bytecode for the VM engine
pub struct SqlCompiler<'a> {
    /// The database containing tables
    pub(crate) database: &'a Database,

    /// Name mapping for tables referenced in the query
    pub(crate) table_map: HashMap<String, String>,

    /// Current bytecode program being generated
    pub(crate) program: Program,

    /// Counter for register allocation
    pub(crate) register_counter: i64,

    /// Whether to generate verbose bytecode with detailed comments
    pub(crate) verbose: bool,

    /// Current outer table alias for correlated subquery detection
    pub(crate) current_outer_alias: Option<String>,

    /// Resolved address of each label, indexed by label id. `None` until
    /// [`SqlCompiler::resolve`] binds it.
    label_addrs: Vec<Option<usize>>,

    /// Jumps awaiting resolution: (instruction address, target label).
    pending_jumps: Vec<(usize, Label)>,

    /// Three-way `Jump`s awaiting resolution:
    /// (instruction address, less, equal, greater).
    pending_jumps_three: Vec<(usize, Label, Label, Label)>,
}

impl<'a> SqlCompiler<'a> {
    /// Create a new SQL compiler
    pub fn new(database: &'a Database, verbose: bool) -> Self {
        SqlCompiler {
            database,
            table_map: HashMap::with_capacity(DEFAULT_CURSOR_CAPACITY),
            program: Program::new(),
            register_counter: 0,
            verbose,
            current_outer_alias: None,
            label_addrs: Vec::new(),
            pending_jumps: Vec::new(),
            pending_jumps_three: Vec::new(),
        }
    }

    /// Create a new, unresolved jump target.
    pub(crate) fn label(&mut self) -> Label {
        self.label_addrs.push(None);
        Label(self.label_addrs.len() - 1)
    }

    /// Bind `label` to the next instruction to be emitted.
    ///
    /// Panics if the label was already resolved -- a label denotes exactly one
    /// address, and rebinding one silently redirects every jump to it.
    pub(crate) fn resolve(&mut self, label: Label) {
        let addr = self.program.len();
        debug_assert!(
            self.label_addrs[label.0].is_none(),
            "label {:?} resolved twice (already at {:?}, now {})",
            label,
            self.label_addrs[label.0],
            addr
        );
        self.label_addrs[label.0] = Some(addr);
    }

    /// Emit a jump instruction whose destination (p2) is `target`.
    ///
    /// The destination is patched in by [`SqlCompiler::finish_labels`], so the
    /// target may be resolved before or after this call.
    pub(crate) fn emit_jump_to(
        &mut self,
        opcode: OpCode,
        p1: i64,
        target: Label,
        p3: i64,
        p4: Option<String>,
        comment: &str,
    ) {
        let addr = self.program.len();
        // p2 is a placeholder; finish_labels overwrites it.
        self.emit(opcode, p1, -1, p3, p4, comment);
        self.pending_jumps.push((addr, target));
    }

    /// Emit a `Jump`: a three-way branch on the most recent `Compare`.
    ///
    /// All three destinations are labels, patched by `finish_labels`.
    pub(crate) fn emit_jump_to_three(
        &mut self,
        less: Label,
        equal: Label,
        greater: Label,
        comment: &str,
    ) {
        let addr = self.program.len();
        self.emit(OpCode::Jump, -1, -1, -1, None, comment);
        self.pending_jumps_three.push((addr, less, equal, greater));
    }

    /// Patch every pending jump with its label's address.
    ///
    /// Called once when a program is finished. An unresolved label means a
    /// code path forgot to mark its destination, which would leave a jump
    /// pointing at the placeholder -- so it fails loudly rather than
    /// generating a program that runs and returns nonsense.
    pub(crate) fn finish_labels(&mut self) -> SqawkResult<()> {
        for (addr, label) in std::mem::take(&mut self.pending_jumps) {
            let target = self.label_addrs[label.0].ok_or_else(|| {
                SqawkError::InvalidSqlQuery(format!(
                    "internal error: jump at {} targets unresolved label {:?}",
                    addr, label
                ))
            })?;
            self.patch_jump(addr, target);
        }
        for (addr, less, equal, greater) in std::mem::take(&mut self.pending_jumps_three) {
            let resolve = |l: Label| -> SqawkResult<i64> {
                self.label_addrs[l.0].map(|a| a as i64).ok_or_else(|| {
                    SqawkError::InvalidSqlQuery(format!(
                        "internal error: Jump at {} targets unresolved label {:?}",
                        addr, l
                    ))
                })
            };
            let (p1, p2, p3) = (resolve(less)?, resolve(equal)?, resolve(greater)?);
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p1 = p1;
                inst.p2 = p2;
                inst.p3 = p3;
            }
        }
        self.label_addrs.clear();
        Ok(())
    }

    /// Allocate a new register and return its index
    pub(crate) fn allocate_register(&mut self) -> i64 {
        let reg = self.register_counter;
        self.register_counter += 1;
        reg
    }

    /// Allocate multiple consecutive registers and return the starting index
    pub(crate) fn allocate_registers(&mut self, count: usize) -> i64 {
        let start = self.allocate_register();
        for _ in 1..count {
            self.allocate_register();
        }
        start
    }

    /// Reset the register counter (used between statements)
    fn reset_registers(&mut self) {
        self.register_counter = 0;
    }

    /// Helper method to emit an instruction
    pub(crate) fn emit(
        &mut self,
        opcode: OpCode,
        p1: i64,
        p2: i64,
        p3: i64,
        p4: Option<String>,
        comment: &str,
    ) {
        self.program.add_instruction(Instruction::new(
            opcode,
            p1,
            p2,
            p3,
            p4,
            0,
            Some(comment.to_string()),
        ));
    }

    /// Helper to emit Column opcodes for multiple columns
    pub(crate) fn emit_column_loads(
        &mut self,
        cursor: i64,
        cols: &[usize],
        start_reg: i64,
        label: &str,
    ) {
        for (i, col_idx) in cols.iter().enumerate() {
            self.emit(
                OpCode::Column,
                cursor,
                *col_idx as i64,
                start_reg + i as i64,
                None,
                &format!("r[{}] = {}.col[{}]", start_reg + i as i64, label, col_idx),
            );
        }
    }

    /// The AggStep/AggFinal function-type word for an aggregate CALL,
    /// including its DISTINCT flag.
    ///
    /// Prefer this over `agg_func_type`, which sees only the name. Four sites
    /// derived the type independently and two of them forgot to OR in
    /// AGG_DISTINCT, so DISTINCT was silently dropped from every aggregate in
    /// a grouped query -- and HAVING, which did set the flag, then failed to
    /// match the aggregate it had been given.
    pub(crate) fn agg_func_type_for(func: &Function) -> i64 {
        let name = func.name.to_string().to_uppercase();
        Self::agg_func_type(&name)
            | if func_is_distinct(func) {
                AGG_DISTINCT
            } else {
                0
            }
    }

    /// Convert aggregate function name to type code
    pub(crate) fn agg_func_type(name: &str) -> i64 {
        match name {
            "COUNT" => AGG_COUNT,
            "SUM" => AGG_SUM,
            "AVG" => AGG_AVG,
            "MIN" => AGG_MIN,
            "MAX" => AGG_MAX,
            _ => AGG_COUNT, // Default to COUNT
        }
    }

    /// Patch a jump instruction's target address (p2)
    pub(crate) fn patch_jump(&mut self, addr: usize, target: usize) {
        if let Some(inst) = self.program.instructions.get_mut(addr) {
            inst.p2 = target as i64;
        }
    }

    /// Emit a comparison operation and return the result register
    pub(crate) fn emit_comparison(
        &mut self,
        op: &BinaryOperator,
        left_reg: i64,
        right_reg: i64,
    ) -> SqawkResult<i64> {
        let result_reg = self.allocate_register();
        let opcode = Self::binary_op_to_comparison_opcode(op)?;

        self.emit(
            opcode,
            left_reg,
            right_reg,
            result_reg,
            None,
            &format!(
                "r[{}] = (r[{}] {:?} r[{}])",
                result_reg, left_reg, op, right_reg
            ),
        );

        Ok(result_reg)
    }

    /// Convert a comparison binary operator to the corresponding OpCode
    pub(crate) fn binary_op_to_comparison_opcode(op: &BinaryOperator) -> SqawkResult<OpCode> {
        match op {
            BinaryOperator::Eq => Ok(OpCode::Eq),
            BinaryOperator::NotEq => Ok(OpCode::Ne),
            BinaryOperator::Lt => Ok(OpCode::Lt),
            BinaryOperator::LtEq => Ok(OpCode::Le),
            BinaryOperator::Gt => Ok(OpCode::Gt),
            BinaryOperator::GtEq => Ok(OpCode::Ge),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported comparison operator: {:?}",
                op
            ))),
        }
    }

    /// Convert SQL type to internal type string
    pub(crate) fn sql_type_to_internal(data_type: &str) -> &'static str {
        match data_type.to_uppercase().as_str() {
            "INTEGER" | "INT" => "INTEGER",
            "REAL" | "FLOAT" | "DOUBLE" => "REAL",
            "BOOLEAN" | "BOOL" => "BOOLEAN",
            _ => "TEXT",
        }
    }

    /// Find a column by table name and column name in a list of tables.
    /// Returns (table_idx, col_idx) if found.
    pub(crate) fn find_column_in_tables(
        table_name: &str,
        col_name: &str,
        tables: &[&Table],
        table_names: &[&str],
    ) -> SqawkResult<(usize, usize)> {
        for (i, name) in table_names.iter().enumerate() {
            if table_name.eq_ignore_ascii_case(name) {
                let columns = tables[i].columns();
                if let Some(col_idx) = columns
                    .iter()
                    .position(|c| c.eq_ignore_ascii_case(col_name))
                {
                    return Ok((i, col_idx));
                } else {
                    return Err(SqawkError::ColumnNotFound(col_name.to_string()));
                }
            }
        }
        Err(SqawkError::TableNotFound(table_name.to_string()))
    }

    /// Build a wildcard schema (SELECT *) from multiple tables.
    /// Returns column indices per table and the result schema.
    pub(crate) fn build_wildcard_schema(
        tables: &[&Table],
        table_names: &[&str],
    ) -> (Vec<Vec<usize>>, ResultSchema) {
        let mut table_cols = Vec::with_capacity(tables.len());
        let mut schema = ResultSchema::new();

        for (i, table) in tables.iter().enumerate() {
            let cols: Vec<usize> = (0..table.column_count()).collect();
            for meta in table.column_metadata() {
                schema.add_column(format!("{}.{}", table_names[i], meta.name), meta.data_type);
            }
            table_cols.push(cols);
        }

        (table_cols, schema)
    }

    // Removed unused add_halt method

    /// Add a comment to the program if verbose mode is enabled
    pub(crate) fn add_comment(&mut self, comment: &str) {
        if self.verbose {
            self.emit(OpCode::Noop, 0, 0, 0, None, comment);
        }
    }

    // Method compile_query_direct removed - will be reimplemented when we update to a newer sqlparser version
    // TODO: Add direct query compilation support

    /// Compile an SQL string into bytecode
    /// Compile a single already-parsed statement into its own program.
    ///
    /// Each statement gets its own program so it can be executed, and its
    /// modifications applied, before the next one is compiled -- which is what
    /// lets a later statement see an earlier one's effects.
    pub fn compile_statement_program(&mut self, statement: &Statement) -> SqawkResult<Program> {
        self.program = Program::new();
        self.reset_registers();
        self.table_map.clear();
        self.label_addrs.clear();
        self.pending_jumps.clear();
        self.pending_jumps_three.clear();

        let init_addr = self.program.len();
        self.emit(OpCode::Init, 0, 0, 0, None, "Start address filled in later");

        self.compile_statement(statement)?;

        self.emit(OpCode::Halt, 0, 0, 0, None, "End execution");

        let start = init_addr + 1;
        if let Some(instruction) = self.program.instructions.get_mut(init_addr) {
            instruction.p2 = start as i64;
            instruction.comment = Some(format!("Start at {}", start).into());
        }

        self.finish_labels()?;
        self.program.register_count = self.register_counter;
        Ok(self.program.clone())
    }

    /// Parse and compile `sql` into a single program.
    ///
    /// Convenience wrapper used by the compiler unit tests, which examine
    /// generated bytecode for one statement. Execution goes through
    /// `compile_statement_program` per statement instead, so that each
    /// statement can observe the previous one's effects.
    #[allow(dead_code)]
    pub fn compile(&mut self, sql: &str) -> SqawkResult<Program> {
        // Reset state for new compilation
        self.program = Program::new();
        self.reset_registers();
        self.table_map.clear();
        self.label_addrs.clear();
        self.pending_jumps.clear();
        self.pending_jumps_three.clear();

        // Parse the SQL statement
        let dialect = HiveDialect {};
        let statements = Parser::parse_sql(&dialect, sql).map_err(SqawkError::SqlParseError)?;

        if statements.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "No SQL statements found".to_string(),
            ));
        }

        // Add initial "Init" instruction that will be filled in later
        // with the address of the main program body
        let init_addr = self.program.len();
        self.emit(
            OpCode::Init,
            0,
            0,
            0,
            None,
            "Start address will be filled in later",
        );

        // Compile each statement
        for statement in statements {
            self.compile_statement(&statement)?;
        }

        // Add Halt instruction at the end
        self.emit(OpCode::Halt, 0, 0, 0, None, "End execution");

        // Go back and update the Init instruction with the correct start address
        // (usually this would point to setup code like transaction start)
        let transaction_addr = init_addr + 1;
        if let Some(instruction) = self.program.instructions.get_mut(init_addr) {
            instruction.p2 = transaction_addr as i64;
            instruction.comment = Some(format!("Start at {}", transaction_addr).into());
        }

        // Patch every symbolic jump now that all addresses are known. This
        // errors rather than emitting a program with a placeholder target.
        self.finish_labels()?;

        // Hand the engine the real register high-water mark.
        self.program.register_count = self.register_counter;

        Ok(self.program.clone())
    }

    // Removed unused compile_statement_into_program method

    /// Compile a single SQL statement
    fn compile_statement(&mut self, statement: &Statement) -> SqawkResult<()> {
        match statement {
            Statement::Query(query) => self.compile_query(query),
            Statement::Insert(insert) => {
                let source = insert.source.as_ref().ok_or_else(|| {
                    SqawkError::UnsupportedSqlFeature("INSERT without a source".into())
                })?;
                // `Insert::columns` became Vec<ObjectName>; sqawk only accepts
                // bare column names, so flatten each to its last segment.
                let columns: Vec<Ident> = insert
                    .columns
                    .iter()
                    .map(|c| Ident::new(object_name_last(c)))
                    .collect();
                self.compile_insert(insert_target(&insert.table)?, &columns, source)
            }
            Statement::Delete(delete) => {
                self.compile_delete(delete_from(&delete.from), delete.selection.as_ref())
            }
            Statement::Update(update) => self.compile_update(
                &update.table,
                &update.assignments,
                update.selection.as_ref(),
            ),
            Statement::CreateTable(create) => {
                if let Some(q) = &create.query {
                    // CREATE TABLE ... AS SELECT
                    self.compile_create_table_as_select(&create.name, q)
                } else {
                    self.compile_create_table(
                        &create.name,
                        &create.columns,
                        &create.hive_formats,
                        &create.location,
                        create_table_options(&create.table_options),
                    )
                }
            }
            Statement::Drop {
                object_type,
                names,
                if_exists,
                ..
            } => self.compile_drop(object_type, names, *if_exists),
            Statement::AlterTable(alter) => {
                // `operation` became `operations`; sqawk handles one at a time.
                match alter.operations.as_slice() {
                    [operation] => self.compile_alter_table(&alter.name, operation),
                    _ => Err(SqawkError::UnsupportedSqlFeature(
                        "ALTER TABLE with multiple operations is not supported".into(),
                    )),
                }
            }
            Statement::Truncate(truncate) => match truncate.table_names.as_slice() {
                [target] => self.compile_truncate(&target.name),
                _ => Err(SqawkError::UnsupportedSqlFeature(
                    "TRUNCATE of multiple tables is not supported".into(),
                )),
            },
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported SQL statement type: {:?}",
                statement
            ))),
        }
    }

    /// Compile a SQL query
    fn compile_query(&mut self, query: &Query) -> SqawkResult<()> {
        // `ORDER BY ALL` carries no key list, so it would otherwise look
        // identical to "no ORDER BY" and be silently ignored. Reject it.
        if is_order_by_all(query) {
            return Err(SqawkError::UnsupportedSqlFeature(
                "ORDER BY ALL is not supported".into(),
            ));
        }

        // Check if we have ORDER BY, LIMIT, or OFFSET
        let has_order_by = !query_order_by(query).is_empty();
        let has_limit = query_limit(query).is_some() || query_offset(query).is_some();

        // Compile the body (SELECT or set operation)
        match &*query.body {
            SetExpr::Select(select) => {
                if has_order_by || has_limit {
                    self.compile_select_with_post_processing(select, query)?;
                } else {
                    self.compile_select(select)?;
                }
            }
            SetExpr::SetOperation {
                op,
                left,
                right,
                set_quantifier,
                ..
            } => {
                let all = *set_quantifier == SetQuantifier::All;
                self.compile_set_operation(op, left, right, all)?;
                // TODO: Handle ORDER BY/LIMIT for set operations
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT statements are supported".to_string(),
                ));
            }
        }

        Ok(())
    }

    /// Compile a set operation (UNION, INTERSECT, EXCEPT)
    fn compile_set_operation(
        &mut self,
        op: &SetOperator,
        left: &SetExpr,
        right: &SetExpr,
        all: bool,
    ) -> SqawkResult<()> {
        self.add_comment(&format!(
            "Set operation: {:?}{}",
            op,
            if all { " ALL" } else { "" }
        ));

        // For INTERSECT and EXCEPT, we need to track where the left results end
        let left_results_marker = match op {
            SetOperator::Intersect | SetOperator::Except => {
                // Use a register to store the count of left-side results
                let marker_reg = self.allocate_register();
                Some(marker_reg)
            }
            _ => None,
        };

        // Compile the left side
        self.compile_set_expr(left)?;

        // For INTERSECT and EXCEPT, record the boundary
        if let Some(marker_reg) = left_results_marker {
            // Add a marker instruction that the VM will use to know where left results end
            // p1=-1 is a special value meaning "use current result count"
            // p2 is the destination register
            self.emit(
                OpCode::Integer,
                -1, // Special marker: -1 means "current result count"
                marker_reg,
                0,
                None,
                "Store current result count",
            );
        }

        // Compile the right side
        self.compile_set_expr(right)?;

        // Add the appropriate set operation opcode
        match op {
            SetOperator::Union => {
                if !all {
                    // UNION (without ALL) needs to remove duplicates
                    self.emit(
                        OpCode::Distinct,
                        0,
                        0,
                        0,
                        None,
                        "Remove duplicate rows for UNION",
                    );
                }
                // UNION ALL: no additional processing needed, results are already combined
            }
            SetOperator::Intersect => {
                self.emit(
                    OpCode::Intersect,
                    left_results_marker.unwrap_or(0),
                    0,
                    0,
                    None,
                    "Keep only rows in both result sets",
                );
            }
            SetOperator::Except | SetOperator::Minus => {
                self.emit(
                    OpCode::Except,
                    left_results_marker.unwrap_or(0),
                    0,
                    0,
                    None,
                    "Keep only rows in left but not in right",
                );
            }
        }

        Ok(())
    }

    /// Compile a set expression (can be a SELECT or nested set operation)
    fn compile_set_expr(&mut self, expr: &SetExpr) -> SqawkResult<()> {
        match expr {
            SetExpr::Select(select) => self.compile_select(select),
            SetExpr::SetOperation {
                op,
                left,
                right,
                set_quantifier,
                ..
            } => {
                let all = *set_quantifier == SetQuantifier::All;
                self.compile_set_operation(op, left, right, all)
            }
            _ => Err(SqawkError::UnsupportedSqlFeature(
                "Unsupported set expression type".to_string(),
            )),
        }
    }

    /// Rewrite `A INNER JOIN B ON cond` into `FROM A, B WHERE cond`.
    ///
    /// The implicit (comma) join path already supports aggregates and GROUP BY;
    /// the explicit-JOIN path does not, and rejects `COUNT(*)` in its
    /// projection resolver. For an INNER join the two spellings mean the same
    /// thing, so an aggregate query over an explicit join is answered by
    /// handing it to the machinery that can already do it, rather than by
    /// duplicating that machinery.
    ///
    /// Returns `None` when the rewrite does not apply: outer joins are NOT
    /// equivalent to a comma join plus WHERE, since the WHERE would discard
    /// exactly the NULL-extended rows the outer join exists to produce.
    fn rewrite_inner_join_as_implicit(select: &Select) -> Option<Select> {
        if select.from.len() != 1 {
            return None;
        }
        let twj = &select.from[0];
        if twj.joins.is_empty() {
            return None;
        }

        let mut froms = vec![TableWithJoins {
            relation: twj.relation.clone(),
            joins: Vec::new(),
        }];
        let mut condition = select.selection.clone();

        for join in &twj.joins {
            let constraint = match classify_join_for_rewrite(&join.join_operator)? {
                Some(c) => c,
                // CROSS JOIN contributes a source but no condition.
                None => {
                    froms.push(TableWithJoins {
                        relation: join.relation.clone(),
                        joins: Vec::new(),
                    });
                    continue;
                }
            };
            let on_expr = match constraint {
                JoinConstraint::On(expr) => expr.clone(),
                _ => return None,
            };
            froms.push(TableWithJoins {
                relation: join.relation.clone(),
                joins: Vec::new(),
            });
            condition = Some(match condition {
                Some(existing) => Expr::BinaryOp {
                    left: Box::new(existing),
                    op: BinaryOperator::And,
                    right: Box::new(on_expr),
                },
                None => on_expr,
            });
        }

        let mut rewritten = select.clone();
        rewritten.from = froms;
        rewritten.selection = condition;
        Some(rewritten)
    }

    /// Compile a SELECT statement
    fn compile_select(&mut self, select: &Select) -> SqawkResult<()> {
        // `GROUP BY ALL` carries no key list, so it would otherwise look
        // identical to "no GROUP BY" and silently collapse the query. Reject it.
        if is_group_by_all(&select.group_by) {
            return Err(SqawkError::UnsupportedSqlFeature(
                "GROUP BY ALL is not supported".into(),
            ));
        }

        if select.from.is_empty() {
            self.compile_select_literal(&select.projection)?;
        } else {
            // Check for implicit join (comma-separated tables in FROM)
            if select.from.len() > 1 {
                // Multiple tables in FROM clause - treat as implicit cross join with WHERE filter
                if self.verbose {
                    eprintln!("Processing multiple tables in FROM clause as CROSS JOINs");
                }

                // Check for GROUP BY or aggregates - requires specialized handling
                let has_group_by = !group_by_exprs(&select.group_by).is_empty();
                let has_aggregates = self.has_aggregates(&select.projection);

                if has_group_by || has_aggregates {
                    // Create a temporary query to pass to compile_implicit_join_with_group_by
                    let query = Query {
                        with: None,
                        body: Box::new(SetExpr::Select(Box::new(select.clone()))),
                        order_by: None,
                        limit_clause: None,
                        fetch: None,
                        locks: vec![],
                        for_clause: None,
                        settings: None,
                        format_clause: None,
                        pipe_operators: vec![],
                    };
                    return self.compile_implicit_join_with_group_by(select, &query);
                }

                return self.compile_implicit_join(select);
            }

            let table_with_joins = &select.from[0];
            if !table_with_joins.joins.is_empty() {
                // An aggregate or GROUP BY over an explicit INNER join is
                // answered by rewriting it to the equivalent comma join, whose
                // path already supports both.
                let needs_aggregation = !group_by_exprs(&select.group_by).is_empty()
                    || self.has_aggregates(&select.projection);
                if needs_aggregation {
                    if let Some(rewritten) = Self::rewrite_inner_join_as_implicit(select) {
                        return self.compile_select(&rewritten);
                    }
                }
                self.compile_join(table_with_joins, &select.projection, &select.selection)?;
            } else {
                // Check for GROUP BY, window functions, or aggregates
                let has_group_by = !group_by_exprs(&select.group_by).is_empty();
                let has_window_functions = self.has_window_functions(&select.projection);
                let has_aggregates = self.has_aggregates(&select.projection);

                if has_window_functions {
                    // Window function query (ROW_NUMBER, RANK, etc. with OVER clause)
                    let table_name = match &table_with_joins.relation {
                        sqlparser::ast::TableFactor::Table { name, .. } => {
                            self.get_table_name(name)?
                        }
                        _ => {
                            return Err(SqawkError::UnsupportedSqlFeature(
                                "Only simple table scans supported".into(),
                            ))
                        }
                    };
                    let table = self.database.get_table(&table_name)?;
                    self.compile_select_with_window(select, table, &table_name)?;
                } else if has_group_by {
                    // GROUP BY query
                    let table_name = match &table_with_joins.relation {
                        sqlparser::ast::TableFactor::Table { name, .. } => {
                            self.get_table_name(name)?
                        }
                        _ => {
                            return Err(SqawkError::UnsupportedSqlFeature(
                                "Only simple table scans supported".into(),
                            ))
                        }
                    };
                    let table = self.database.get_table(&table_name)?;
                    self.compile_select_with_group_by(select, table, &table_name)?;
                } else if has_aggregates {
                    // Aggregate without GROUP BY - entire table is one group
                    let table_name = match &table_with_joins.relation {
                        sqlparser::ast::TableFactor::Table { name, .. } => {
                            self.get_table_name(name)?
                        }
                        _ => {
                            return Err(SqawkError::UnsupportedSqlFeature(
                                "Only simple table scans supported".into(),
                            ))
                        }
                    };
                    let table = self.database.get_table(&table_name)?;
                    self.compile_select_with_aggregate(select, table, &table_name)?;
                } else {
                    self.compile_table_scan(
                        table_with_joins,
                        &select.projection,
                        &select.selection,
                    )?;
                }
            }
        }

        // Handle DISTINCT - emit Distinct opcode to deduplicate results
        if select.distinct.is_some() {
            self.emit(OpCode::Distinct, 0, 0, 0, None, "Remove duplicate rows");
        }

        Ok(())
    }

    /// Compile a SELECT with ORDER BY and/or LIMIT/OFFSET
    fn compile_select_with_post_processing(
        &mut self,
        select: &Select,
        query: &Query,
    ) -> SqawkResult<()> {
        let has_order_by = !query_order_by(query).is_empty();

        if select.from.is_empty() {
            self.compile_select_literal(&select.projection)?;
            return Ok(());
        }

        // Check for implicit join (comma-separated tables in FROM)
        if select.from.len() > 1 {
            // Multiple tables in FROM clause
            if self.verbose {
                eprintln!("Processing multiple tables in FROM clause as CROSS JOINs");
            }

            // Check for GROUP BY or aggregates - requires specialized handling
            let has_group_by = !group_by_exprs(&select.group_by).is_empty();
            let has_aggregates = self.has_aggregates(&select.projection);

            if has_group_by || has_aggregates {
                // Multi-table query with GROUP BY or aggregates. Like the
                // single-table grouped path, this emits rows directly, so
                // ORDER BY and LIMIT are applied to the finished result set --
                // both were silently dropped here.
                self.compile_implicit_join_with_group_by(select, query)?;
                return self.emit_result_post_processing(select, query);
            }

            if !query_order_by(query).is_empty() {
                // ORDER BY needs the whole result before it can sort, so the
                // scan must NOT apply LIMIT as it goes -- doing so would keep
                // the first N rows and then sort those, rather than the top N.
                // Sorting and limiting both happen afterwards.
                self.compile_implicit_join(select)?;
                return self.emit_result_post_processing(select, query);
            }

            return self.compile_implicit_join_with_query(select, query);
        }

        let table_with_joins = &select.from[0];

        // Check for explicit JOINs (FROM table1 JOIN table2 ON ...)
        if !table_with_joins.joins.is_empty() {
            // See compile_select: aggregates over an explicit INNER join are
            // handled by rewriting to the comma-join form.
            let needs_aggregation = !group_by_exprs(&select.group_by).is_empty()
                || self.has_aggregates(&select.projection);
            if needs_aggregation {
                if let Some(rewritten) = Self::rewrite_inner_join_as_implicit(select) {
                    return self.compile_select_with_post_processing(&rewritten, query);
                }
            }
            // A join emits rows directly rather than through the cursor-based
            // sorter, which is why ORDER BY used to be dropped here outright.
            // Sorting the finished result set works regardless of how many
            // cursors produced it.
            self.compile_join(table_with_joins, &select.projection, &select.selection)?;
            self.emit_result_post_processing(select, query)?;
            return Ok(());
        }

        // Get table and columns for ORDER BY resolution
        let table_name = match &table_with_joins.relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table scans supported".into(),
                ))
            }
        };

        if !self.database.has_table(&table_name) {
            return Err(SqawkError::TableNotFound(table_name));
        }

        let table = self.database.get_table(&table_name).unwrap();

        // Check for GROUP BY - delegate to specialized handler
        // GROUP BY with ORDER BY/LIMIT handles these internally
        let has_group_by = !group_by_exprs(&select.group_by).is_empty();
        let has_aggregates = self.has_aggregates(&select.projection);

        if has_group_by || has_aggregates {
            if has_group_by {
                self.compile_select_with_group_by(select, table, &table_name)?;
            } else {
                self.compile_select_with_aggregate(select, table, &table_name)?;
            }
            // These paths emit rows directly rather than through the sorter,
            // so ORDER BY and LIMIT are applied to the finished result set.
            // `query` used to be in scope here and simply never passed on,
            // which is why both were silently dropped on every grouped query.
            self.emit_result_post_processing(select, query)?;
            return Ok(());
        }

        // Check if projection contains function expressions or computed expressions
        let has_computed_expr = Self::projection_needs_expr(&select.projection);

        // If we have functions/computed expressions and only LIMIT (no ORDER BY), use compile_table_scan
        // which handles function expressions properly
        if has_computed_expr && !has_order_by {
            return self.compile_table_scan_with_limit(select, query, &table_name);
        }

        let columns = self.resolve_projection(&select.projection, table)?;

        // Build result schema with column names and types
        let schema = self.build_result_schema(&select.projection, table);
        self.program.set_result_schema(schema);

        if has_order_by {
            self.compile_select_with_sorter(select, query, table, &columns, &table_name)?;
        } else {
            self.compile_select_with_limit(select, query, table, &columns, &table_name)?;
        }

        Ok(())
    }

    /// Compile SELECT with ORDER BY using a sorter
    fn compile_select_with_sorter(
        &mut self,
        select: &Select,
        query: &Query,
        table: &Table,
        columns: &[usize],
        table_name: &str,
    ) -> SqawkResult<()> {
        let cursor_idx = 0i64;
        let sorter_id = 0i64;
        let col_count = columns.len();

        // Sorter payload is [sort keys.., output columns..].
        //
        // It used to hold only the output columns, and the sort spec mapped
        // each ORDER BY key to a position among them -- so ordering by a
        // column you did not select was rejected with "ORDER BY column must be
        // in SELECT list", and ordering by an expression was rejected outright.
        // Carrying the keys separately removes both restrictions: a key is
        // just another value computed per row, whether or not it is projected.
        let order_by = query_order_by(query);
        let key_count = order_by.len();
        let total_cols = key_count + col_count;

        let sort_spec: String = order_by
            .iter()
            .enumerate()
            .map(|(i, ob)| format!("{}:{}", i, if order_by_is_asc(ob) { "asc" } else { "desc" }))
            .collect::<Vec<_>>()
            .join(",");

        // Open sorter
        self.emit(
            OpCode::SorterOpen,
            sorter_id,
            total_cols as i64,
            0,
            Some(sort_spec),
            "",
        );

        // Open table
        self.emit(
            OpCode::OpenRead,
            cursor_idx,
            1,
            0,
            Some(table_name.to_string()),
            "",
        );

        // Rewind - jump past loop if empty
        let rewind_addr = self.program.len();
        self.emit(
            OpCode::Rewind,
            cursor_idx,
            0, // Will be patched
            0,
            None,
            "",
        );

        let loop_start = self.program.len();

        // WHERE first, so filtered rows never reach the sorter.
        let next_label = self.label();
        if let Some(where_expr) = &select.selection {
            let cond_reg = self.compile_where_condition(where_expr, table, cursor_idx as usize)?;
            self.emit_jump_to(
                OpCode::IfZ,
                cond_reg,
                next_label,
                0,
                None,
                "Skip row if WHERE is false",
            );
        }

        // One contiguous block: sort keys first, then the output columns.
        let start_reg = self.allocate_registers(total_cols);

        let ctx = NameCtx::single(table, cursor_idx);
        for (i, ob) in order_by.iter().enumerate() {
            let dest = start_reg + i as i64;
            // `ORDER BY 2` names the second output column, it is not the
            // constant 2.
            if let Some(out_idx) = Self::order_by_ordinal(&ob.expr, col_count)? {
                let col_idx = columns[out_idx];
                self.emit(
                    OpCode::Column,
                    cursor_idx,
                    col_idx as i64,
                    dest,
                    None,
                    &format!("r[{}] = ORDER BY position {}", dest, out_idx + 1),
                );
            } else {
                self.code_expr(&ob.expr, &ctx, Some(dest))?;
            }
        }

        for (i, col_idx) in columns.iter().enumerate() {
            self.emit(
                OpCode::Column,
                cursor_idx,
                *col_idx as i64,
                start_reg + (key_count + i) as i64,
                None,
                "",
            );
        }

        // Insert into sorter
        self.emit(
            OpCode::SorterInsert,
            sorter_id,
            start_reg,
            total_cols as i64,
            None,
            "",
        );

        // Next row
        self.resolve(next_label);
        self.emit(OpCode::Next, cursor_idx, loop_start as i64, 0, None, "");

        let after_scan = self.program.len();

        // Patch rewind jump
        if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
            inst.p2 = after_scan as i64;
        }

        // Sort the sorter
        self.emit(OpCode::SorterSort, sorter_id, 0, 0, None, "");

        // Handle LIMIT/OFFSET
        // When DISTINCT is present, we apply LIMIT after DISTINCT (as a separate opcode)
        // because DISTINCT may reduce the row count
        let has_distinct = select.distinct.is_some();
        let (limit_val, offset_val) = self.extract_limit_offset(query)?;

        // Only apply LIMIT during sorter output if DISTINCT is not present
        let limit_reg = if !has_distinct && (limit_val.is_some() || offset_val > 0) {
            let reg = self.allocate_register();
            // Initialize limit counter (add offset to limit since we'll skip offset rows)
            let total = limit_val.unwrap_or(i64::MAX);
            self.emit(OpCode::Integer, total, reg, 0, None, "");
            Some(reg)
        } else {
            None
        };

        // Only apply offset during sorter output if DISTINCT is NOT present
        // When DISTINCT is present, offset is applied after DISTINCT via the Limit opcode
        let offset_reg = if offset_val > 0 && !has_distinct {
            let reg = self.allocate_register();
            self.emit(OpCode::Integer, offset_val, reg, 0, None, "");
            Some(reg)
        } else {
            None
        };

        // Emit sorted results
        let sorter_loop_start = self.program.len();

        // Get row from sorter
        self.emit(
            OpCode::SorterData,
            sorter_id,
            start_reg,
            total_cols as i64,
            None,
            "",
        );

        // Symbolic targets for the drain loop. Using labels here matters
        // because whether a LIMIT instruction exists changes the distance
        // between the OFFSET logic and SorterNext -- the exact coupling that
        // the old `skip_offset = if limit_reg.is_some() { 3 } else { 2 }`
        // encoded by hand.
        let result_row_label = self.label();
        let sorter_next_label = self.label();
        let after_loop_label = self.label();

        // Handle OFFSET - skip first N rows
        if let Some(off_reg) = offset_reg {
            let decrement_label = self.label();

            // If offset counter > 0, decrement and skip this row
            self.emit_jump_to(
                OpCode::IfPos,
                off_reg,
                decrement_label,
                0,
                None,
                "offset remaining -> skip this row",
            );
            // Offset exhausted, continue to output
            self.emit_jump_to(
                OpCode::Goto,
                0,
                result_row_label,
                0,
                None,
                "offset exhausted -> output row",
            );

            self.resolve(decrement_label);
            // Decrement offset, then fall through to the skip.
            let continue_label = self.label();
            self.emit_jump_to(OpCode::DecrJumpZero, off_reg, continue_label, 0, None, "");
            self.resolve(continue_label);
            self.emit_jump_to(OpCode::Goto, 0, sorter_next_label, 0, None, "skip row");
        }

        // Output result row
        self.resolve(result_row_label);
        // Emit only the output half: the sort keys are internal.
        self.emit(
            OpCode::ResultRow,
            start_reg + key_count as i64,
            col_count as i64,
            0,
            None,
            "",
        );

        // Handle LIMIT
        if let Some(lim_reg) = limit_reg {
            // DecrJumpZero exits when limit reached
            self.emit_jump_to(
                OpCode::DecrJumpZero,
                lim_reg,
                after_loop_label,
                0,
                None,
                "limit reached -> exit loop",
            );
        }

        // Next sorted row
        self.resolve(sorter_next_label);
        self.emit(
            OpCode::SorterNext,
            sorter_id,
            sorter_loop_start as i64,
            0,
            None,
            "",
        );

        // Close cursor
        self.resolve(after_loop_label);
        self.emit(OpCode::Close, cursor_idx, 0, 0, None, "");

        // Handle DISTINCT - emit Distinct opcode to deduplicate results
        if select.distinct.is_some() {
            self.emit(OpCode::Distinct, 0, 0, 0, None, "Remove duplicate rows");

            // For DISTINCT queries, apply LIMIT/OFFSET after DISTINCT
            // OFFSET was NOT applied during sorter output when DISTINCT is present
            if limit_val.is_some() || offset_val > 0 {
                self.emit(
                    OpCode::Limit,
                    limit_val.unwrap_or(i64::MAX),
                    offset_val,
                    0,
                    None,
                    &format!(
                        "Limit {} offset {}",
                        limit_val.unwrap_or(i64::MAX),
                        offset_val
                    ),
                );
            }
        }

        Ok(())
    }

    /// Compile SELECT with LIMIT/OFFSET (no ORDER BY)
    fn compile_select_with_limit(
        &mut self,
        select: &Select,
        query: &Query,
        table: &Table,
        columns: &[usize],
        table_name: &str,
    ) -> SqawkResult<()> {
        let cursor_idx = 0i64;
        let col_count = columns.len();

        let (limit_val, offset_val) = self.extract_limit_offset(query)?;

        // Open table
        self.emit(
            OpCode::OpenRead,
            cursor_idx,
            1,
            0,
            Some(table_name.to_string()),
            "",
        );

        // Initialize limit counter
        let limit_reg = if let Some(limit) = limit_val {
            let reg = self.allocate_register();
            self.emit(OpCode::Integer, limit, reg, 0, None, "");
            Some(reg)
        } else {
            None
        };

        // LIMIT 0 optimization: skip the entire loop if limit is 0 at compile time
        let limit_zero_jump = if limit_val == Some(0) {
            let addr = self.program.len();
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to after loop
                0,
                None,
                "LIMIT 0: skip loop",
            );
            Some(addr)
        } else {
            None
        };

        // Initialize offset counter
        let offset_reg = if offset_val > 0 {
            let reg = self.allocate_register();
            self.emit(OpCode::Integer, offset_val, reg, 0, None, "");
            Some(reg)
        } else {
            None
        };

        // Rewind
        let rewind_addr = self.program.len();
        self.emit(
            OpCode::Rewind,
            cursor_idx,
            0, // Will be patched
            0,
            None,
            "",
        );

        let loop_start = self.program.len();

        // Load columns
        let start_reg = self.allocate_registers(col_count);

        for (i, col_idx) in columns.iter().enumerate() {
            self.emit(
                OpCode::Column,
                cursor_idx,
                *col_idx as i64,
                start_reg + i as i64,
                None,
                "",
            );
        }

        // A row that fails WHERE must resume at Next -- NOT at a fixed offset.
        // The distance from here to Next depends on whether OFFSET and LIMIT
        // emit instructions, so the old `program.len() + 2` landed on the
        // LIMIT counter's DecrJumpZero (making LIMIT count rows *scanned*
        // rather than rows *returned*) or, with OFFSET, on ResultRow itself.
        let next_label = self.label();

        // WHERE clause
        if let Some(where_expr) = &select.selection {
            let cond_reg = self.compile_where_condition(where_expr, table, cursor_idx as usize)?;
            self.emit_jump_to(
                OpCode::IfZ,
                cond_reg,
                next_label,
                0,
                None,
                "Skip row if WHERE is false",
            );
        }

        // Handle OFFSET - skip first N matching rows
        // Pattern: IfPos offset, skip -> output -> skip: DecrJumpZero -> Next
        let offset_ifpos_addr = if let Some(off_reg) = offset_reg {
            let addr = self.program.len();
            self.emit(
                OpCode::IfPos,
                off_reg,
                0, // Will patch to DecrJumpZero (skip block)
                0,
                None,
                "",
            );
            Some(addr)
        } else {
            None
        };

        // Output row
        self.emit(OpCode::ResultRow, start_reg, col_count as i64, 0, None, "");

        // Handle LIMIT
        let after_limit = if let Some(lim_reg) = limit_reg {
            self.emit(
                OpCode::DecrJumpZero,
                lim_reg,
                0, // Will be patched to after loop
                0,
                None,
                "",
            );
            Some(self.program.len() - 1)
        } else {
            None
        };

        // Goto past offset decrement (skip block) to Next
        let goto_next_addr = if offset_reg.is_some() {
            let addr = self.program.len();
            self.emit(
                OpCode::Goto,
                0,
                0, // Will patch to Next
                0,
                None,
                "",
            );
            Some(addr)
        } else {
            None
        };

        // Offset skip block: decrement offset counter then fall through to Next
        let offset_decr_addr = if let Some(off_reg) = offset_reg {
            let addr = self.program.len();
            self.emit(
                OpCode::DecrJumpZero,
                off_reg,
                (self.program.len() + 1) as i64, // Always fall through to Next
                0,
                None,
                "",
            );
            Some(addr)
        } else {
            None
        };

        // Next row
        let next_addr = self.program.len();
        self.resolve(next_label);
        self.emit(OpCode::Next, cursor_idx, loop_start as i64, 0, None, "");

        let after_loop = self.program.len();

        // Patch jumps
        if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
            inst.p2 = after_loop as i64;
        }
        if let Some(addr) = after_limit {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = after_loop as i64;
            }
        }
        // Patch offset IfPos to jump to decrement block
        if let Some(ifpos_addr) = offset_ifpos_addr {
            if let Some(decr_addr) = offset_decr_addr {
                if let Some(inst) = self.program.instructions.get_mut(ifpos_addr) {
                    inst.p2 = decr_addr as i64;
                }
            }
        }
        // Patch Goto to jump to Next
        if let Some(goto_addr) = goto_next_addr {
            if let Some(inst) = self.program.instructions.get_mut(goto_addr) {
                inst.p2 = next_addr as i64;
            }
        }
        // Patch LIMIT 0 optimization Goto to jump past loop
        if let Some(goto_addr) = limit_zero_jump {
            if let Some(inst) = self.program.instructions.get_mut(goto_addr) {
                inst.p2 = after_loop as i64;
            }
        }

        // Close cursor
        self.emit(OpCode::Close, cursor_idx, 0, 0, None, "");

        Ok(())
    }

    /// Extract LIMIT and OFFSET values from query
    pub(crate) fn extract_limit_offset(&self, query: &Query) -> SqawkResult<(Option<i64>, i64)> {
        let limit = if let Some(limit_expr) = query_limit(query) {
            match limit_expr {
                Expr::Value(ValueWithSpan {
                    value: Value::Number(n, _),
                    ..
                }) => Some(n.parse::<i64>().map_err(|_| {
                    SqawkError::InvalidSqlQuery(format!("Invalid LIMIT value: {}", n))
                })?),
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only constant LIMIT supported".into(),
                    ))
                }
            }
        } else {
            None
        };

        let offset = if let Some(offset_clause) = query_offset(query) {
            match offset_clause {
                Expr::Value(ValueWithSpan {
                    value: Value::Number(n, _),
                    ..
                }) => n.parse::<i64>().map_err(|_| {
                    SqawkError::InvalidSqlQuery(format!("Invalid OFFSET value: {}", n))
                })?,
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only constant OFFSET supported".into(),
                    ))
                }
            }
        } else {
            0
        };

        Ok((limit, offset))
    }

    /// Compile a SELECT statement with literals (e.g., SELECT 1, SELECT 'text')
    fn compile_select_literal(&mut self, projection: &[SelectItem]) -> SqawkResult<()> {
        self.add_comment("Literal value query (no table)");

        // For each selected literal, add an instruction to load it into a register
        let mut result_regs = Vec::new();

        for item in projection.iter() {
            match item {
                SelectItem::UnnamedExpr(expr) => {
                    // Compile a simple expression and store the value in a register
                    let reg = self.compile_expr(expr)?;
                    result_regs.push(reg);
                }
                SelectItem::ExprWithAlias { expr, alias } => {
                    // Same as UnnamedExpr but with an alias (column name)
                    let reg = self.compile_expr(expr)?;
                    result_regs.push(reg);

                    // We don't need to do anything special with the alias for now
                    // But we could store it for the result table column names
                    if self.verbose {
                        self.add_comment(&format!("Column alias: {}", alias));
                    }
                }
                _ => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Only simple expressions supported in SELECT without FROM".to_string(),
                    ));
                }
            }
        }

        // Generate the result row
        if !result_regs.is_empty() {
            // ResultRow requires contiguous registers, but compile_expr may have
            // allocated non-contiguous registers. Copy results to contiguous block.
            let start_reg = self.allocate_registers(result_regs.len());

            // Copy each result to the contiguous block
            for (i, &src_reg) in result_regs.iter().enumerate() {
                let dest_reg = start_reg + i as i64;
                if src_reg != dest_reg {
                    self.emit(
                        OpCode::Copy,
                        src_reg,
                        dest_reg,
                        0,
                        None,
                        &format!("Copy r[{}] -> r[{}]", src_reg, dest_reg),
                    );
                }
            }

            // Output the result row from contiguous registers
            self.emit(
                OpCode::ResultRow,
                start_reg,                // First register
                result_regs.len() as i64, // Number of columns
                0,
                None,
                "Output literal result row",
            );
        }

        Ok(())
    }

    /// Compile an expression into a specific register
    pub(crate) fn compile_expr_into_register(
        &mut self,
        expr: &sqlparser::ast::Expr,
        target_reg: usize,
    ) -> SqawkResult<()> {
        // Compile the expression
        let src_reg = self.compile_expr(expr)?;

        // If not already in target register, copy
        if src_reg != target_reg as i64 {
            self.emit(
                OpCode::Copy,
                src_reg,
                target_reg as i64,
                0,
                None,
                "Copy expr result to target",
            );
        }

        Ok(())
    }

    /// Compile an expression into bytecode and return the register containing the result
    fn compile_expr(&mut self, expr: &sqlparser::ast::Expr) -> SqawkResult<i64> {
        let result_reg = self.allocate_register();

        match expr {
            sqlparser::ast::Expr::Value(ValueWithSpan { value, .. }) => {
                // Load the appropriate value based on type
                match value {
                    sqlparser::ast::Value::Number(num, _) => {
                        // Try to parse as integer first
                        if let Ok(int_val) = num.parse::<i64>() {
                            self.emit(
                                OpCode::Integer,
                                int_val,    // Value
                                result_reg, // Target register
                                0,
                                None,
                                &format!("r[{}] = {}", result_reg, int_val),
                            );
                        } else if let Ok(float_val) = num.parse::<f64>() {
                            // For floats, use String opcode and rely on runtime conversion
                            self.emit(
                                OpCode::String,
                                0,
                                result_reg,
                                0,
                                Some(float_val.to_string()),
                                &format!("r[{}] = {} (float)", result_reg, float_val),
                            );
                        } else {
                            return Err(SqawkError::UnsupportedSqlFeature(format!(
                                "Invalid numeric literal: {}",
                                num
                            )));
                        }
                    }
                    sqlparser::ast::Value::SingleQuotedString(s) => {
                        self.emit(
                            OpCode::String,
                            0,
                            result_reg,
                            0,
                            Some(s.clone()),
                            &format!("r[{}] = '{}'", result_reg, s),
                        );
                    }
                    sqlparser::ast::Value::Null => {
                        self.emit(
                            OpCode::Null,
                            0,
                            result_reg,
                            0,
                            None,
                            &format!("r[{}] = NULL", result_reg),
                        );
                    }
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported literal type: {:?}",
                            value
                        )));
                    }
                }
            }
            sqlparser::ast::Expr::UnaryOp { op, expr } => {
                // Handle unary operators (e.g., -5, +3)
                match op {
                    sqlparser::ast::UnaryOperator::Minus => {
                        // Compile the inner expression
                        let inner_reg = self.compile_expr(expr)?;
                        // Negate using 0 - value (avoids Integer -1 special case)
                        let zero_reg = self.allocate_register();
                        self.emit(
                            OpCode::Integer,
                            0,
                            zero_reg,
                            0,
                            None,
                            &format!("r[{}] = 0", zero_reg),
                        );
                        self.emit(
                            OpCode::Subtract,
                            zero_reg,
                            inner_reg,
                            result_reg,
                            None,
                            &format!("r[{}] = -r[{}]", result_reg, inner_reg),
                        );
                    }
                    sqlparser::ast::UnaryOperator::Plus => {
                        // Unary plus is a no-op, just compile the inner expression
                        let inner_reg = self.compile_expr(expr)?;
                        self.emit(
                            OpCode::Copy,
                            inner_reg,
                            result_reg,
                            0,
                            None,
                            &format!("r[{}] = +r[{}]", result_reg, inner_reg),
                        );
                    }
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported unary operator: {:?}",
                            op
                        )));
                    }
                }
            }
            sqlparser::ast::Expr::BinaryOp { left, op, right } => {
                // Handle arithmetic binary operators
                let left_reg = self.compile_expr(left)?;
                let right_reg = self.compile_expr(right)?;

                let opcode = match op {
                    sqlparser::ast::BinaryOperator::Plus => OpCode::Add,
                    sqlparser::ast::BinaryOperator::Minus => OpCode::Subtract,
                    sqlparser::ast::BinaryOperator::Multiply => OpCode::Multiply,
                    sqlparser::ast::BinaryOperator::Divide => OpCode::Divide,
                    sqlparser::ast::BinaryOperator::Modulo => OpCode::Remainder,
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported binary operator: {:?}",
                            op
                        )));
                    }
                };

                self.emit(
                    opcode,
                    left_reg,
                    right_reg,
                    result_reg,
                    None,
                    &format!(
                        "r[{}] = r[{}] {:?} r[{}]",
                        result_reg, left_reg, op, right_reg
                    ),
                );
            }
            sqlparser::ast::Expr::Function(func) => {
                // Handle function calls (ABS, ROUND, etc.)
                let func_name = func
                    .name
                    .0
                    .iter()
                    .map(|id| id.as_ident().map(|i| i.value.as_str()).unwrap_or_default())
                    .collect::<Vec<_>>()
                    .join(".")
                    .to_uppercase();

                match func_name.as_str() {
                    "ABS" | "ROUND" | "CEIL" | "CEILING" | "FLOOR" => {
                        if func_args(func).is_empty() {
                            return Err(SqawkError::InvalidSqlQuery(format!(
                                "{} requires one argument",
                                func_name
                            )));
                        }
                        let arg_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
                        let src_reg = self.compile_expr(&arg_expr)?;
                        // P3 is the register holding ROUND's precision; -1
                        // means the call had no second argument. Zero would
                        // name register 0, so it must not be used as "none".
                        let prec_reg = if func_name == "ROUND" && func_args(func).len() > 1 {
                            let prec_expr = self.extract_function_arg_expr(&func_args(func)[1])?;
                            self.compile_expr(&prec_expr)?
                        } else {
                            -1
                        };
                        self.emit(
                            OpCode::MathFunc,
                            src_reg,
                            result_reg,
                            prec_reg,
                            Some(func_name.clone()),
                            &format!("r[{}] = {}(r[{}])", result_reg, func_name, src_reg),
                        );
                    }
                    "NOW" | "CURRENT_TIMESTAMP" | "CURRENT_DATE" | "CURRENT_TIME" => {
                        // No-argument date/time functions
                        self.emit(
                            OpCode::DateFunc,
                            0, // No source register needed
                            result_reg,
                            0,
                            Some(func_name.clone()),
                            &format!("r[{}] = {}()", result_reg, func_name),
                        );
                    }
                    "DATE" | "TIME" => {
                        // Single-argument date/time functions
                        if func_args(func).is_empty() {
                            return Err(SqawkError::InvalidSqlQuery(format!(
                                "{} requires one argument",
                                func_name
                            )));
                        }
                        let arg_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
                        let src_reg = self.compile_expr(&arg_expr)?;
                        self.emit(
                            OpCode::DateFunc,
                            src_reg,
                            result_reg,
                            0,
                            Some(func_name.clone()),
                            &format!("r[{}] = {}(r[{}])", result_reg, func_name, src_reg),
                        );
                    }
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported function in expression: {}",
                            func_name
                        )));
                    }
                }
            }
            sqlparser::ast::Expr::Ceil { expr, .. } => {
                // CEIL is a special expression type in sqlparser
                let src_reg = self.compile_expr(expr)?;
                self.emit(
                    OpCode::MathFunc,
                    src_reg,
                    result_reg,
                    -1,
                    Some("CEIL".to_string()),
                    &format!("r[{}] = CEIL(r[{}])", result_reg, src_reg),
                );
            }
            sqlparser::ast::Expr::Floor { expr, .. } => {
                // FLOOR is a special expression type in sqlparser
                let src_reg = self.compile_expr(expr)?;
                self.emit(
                    OpCode::MathFunc,
                    src_reg,
                    result_reg,
                    -1,
                    Some("FLOOR".to_string()),
                    &format!("r[{}] = FLOOR(r[{}])", result_reg, src_reg),
                );
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Unsupported expression type: {:?}",
                    expr
                )));
            }
        }

        Ok(result_reg)
    }

    /// Compile a table scan with optional WHERE clause
    fn compile_table_scan(
        &mut self,
        table_with_joins: &TableWithJoins,
        projection: &[SelectItem],
        where_clause: &Option<Expr>,
    ) -> SqawkResult<()> {
        // Get the table name and alias
        let (table_name, table_alias) = match &table_with_joins.relation {
            sqlparser::ast::TableFactor::Table { name, alias, .. } => {
                let tname = self.get_table_name(name)?;
                let talias = alias.as_ref().map(|a| a.name.value.clone());
                (tname, talias)
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table scans are supported".into(),
                ))
            }
        };

        // Set the current outer alias for correlated subquery detection
        self.current_outer_alias = table_alias;

        // Check if the table exists by trying to get it
        if !self.database.has_table(&table_name) {
            return Err(SqawkError::TableNotFound(table_name));
        }

        let table = self.database.get_table(&table_name).unwrap();

        // Check if projection contains function expressions or computed expressions
        let has_function_expr = Self::projection_needs_expr(projection);

        // Build result schema with column names and types
        let schema = self.build_result_schema(projection, table);
        self.program.set_result_schema(schema);

        self.add_comment(&format!("Scanning table: {}", table_name));

        // Open the table for reading (cursor 0)
        let cursor_idx = 0;
        // Use a simple counter for now, since we don't have get_table_id
        let table_id = 1i64; // Just assign a default ID

        self.emit(
            OpCode::OpenRead,
            cursor_idx as i64,
            table_id,
            0,
            Some(table_name.clone()),
            &format!("Open table {} for reading", table_name),
        );

        // Set up the loop to scan the table
        // Store the rewind address to patch later with correct exit point
        let rewind_addr = self.program.len();
        self.emit(
            OpCode::Rewind,
            cursor_idx as i64,
            0, // Placeholder - will be patched with actual exit address
            0,
            None,
            "Position cursor at first row",
        );

        // Loop body start address
        let loop_addr = self.program.len();

        // Load projection values into registers
        let mut result_regs = Vec::new();
        if has_function_expr {
            // Pre-allocate all result registers to ensure they are contiguous
            let num_items = projection.len();
            for _ in 0..num_items {
                let value_reg = self.allocate_register();
                result_regs.push(value_reg);
            }

            // Handle projection with function expressions
            for (idx, item) in projection.iter().enumerate() {
                let value_reg = result_regs[idx];

                match item {
                    // Multiple aliases for one item (`expr AS (a, b)`) is a
                    // non-standard extension sqawk does not implement.
                    SelectItem::ExprWithAliases { .. } => {
                        return Err(SqawkError::UnsupportedSqlFeature(
                            "Multiple column aliases are not supported".into(),
                        ))
                    }
                    SelectItem::Wildcard(_) => {
                        // For wildcard, load all columns
                        for col_idx in 0..table.column_count() {
                            if col_idx > 0 {
                                let extra_reg = self.allocate_register();
                                result_regs.push(extra_reg);
                                self.emit(
                                    OpCode::Column,
                                    cursor_idx as i64,
                                    col_idx as i64,
                                    extra_reg,
                                    None,
                                    &format!("r[{}] = column {}", extra_reg, col_idx),
                                );
                            } else {
                                self.emit(
                                    OpCode::Column,
                                    cursor_idx as i64,
                                    0,
                                    value_reg,
                                    None,
                                    &format!("r[{}] = column 0", value_reg),
                                );
                            }
                        }
                    }
                    SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. } => {
                        // One expression compiler, as everywhere else. This was
                        // a parallel implementation understanding Function,
                        // Trim, Substring, Position, Overlay, BinaryOp, UnaryOp,
                        // Ceil and Floor, and rejecting everything else -- so
                        // IS NULL, LIKE, BETWEEN, IN and subqueries were
                        // unusable in a projection despite being supported in
                        // WHERE.
                        let ctx = NameCtx::single(table, cursor_idx as i64);
                        self.code_expr(expr, &ctx, Some(value_reg))?;
                    }
                    SelectItem::QualifiedWildcard(_, _) => {
                        for col_idx in 0..table.column_count() {
                            if col_idx > 0 {
                                let extra_reg = self.allocate_register();
                                result_regs.push(extra_reg);
                                self.emit(
                                    OpCode::Column,
                                    cursor_idx as i64,
                                    col_idx as i64,
                                    extra_reg,
                                    None,
                                    &format!("r[{}] = column {}", extra_reg, col_idx),
                                );
                            } else {
                                self.emit(
                                    OpCode::Column,
                                    cursor_idx as i64,
                                    0,
                                    value_reg,
                                    None,
                                    &format!("r[{}] = column 0", value_reg),
                                );
                            }
                        }
                    }
                }
            }
        } else {
            // Original path for simple column references
            let columns = self.resolve_projection(projection, table)?;
            for col_idx in columns.iter() {
                let value_reg = self.allocate_register();
                result_regs.push(value_reg);

                self.emit(
                    OpCode::Column,
                    cursor_idx as i64,
                    *col_idx as i64,
                    value_reg,
                    None,
                    &format!("r[{}] = column {} value", value_reg, col_idx),
                );
            }
        }

        // Compile WHERE clause filtering if present
        if let Some(where_expr) = where_clause {
            self.add_comment("WHERE clause filtering");
            if self.verbose {
                eprintln!("WHERE comparison: {:?}", where_expr);
            }
            let skip_addr = self.compile_where_condition(where_expr, table, cursor_idx)?;

            // If WHERE condition failed, jump to Next instruction to skip this row
            self.emit(
                OpCode::IfZ,
                skip_addr,                       // Register containing condition result
                (self.program.len() + 2) as i64, // Jump to Next instruction
                0,
                None,
                "Skip row if WHERE condition is false",
            );
        }

        // Output the result row (only reached if WHERE condition passes)
        self.emit(
            OpCode::ResultRow,
            result_regs[0],           // First register in result
            result_regs.len() as i64, // Number of columns
            0,
            None,
            "Output result row",
        );

        // Move to next row and continue loop
        self.emit(
            OpCode::Next,
            cursor_idx as i64,
            loop_addr as i64, // Jump back to start of loop for next row
            0,
            None,
            "Move to next row or exit loop",
        );

        // Close the table cursor
        // First, get the close instruction address (this is where Rewind should jump on empty table)
        let close_addr = self.program.len();
        self.emit(OpCode::Close, cursor_idx as i64, 0, 0, None, "Close cursor");

        // Patch the Rewind instruction to jump to Close on empty table
        if let Some(rewind_inst) = self.program.instructions.get_mut(rewind_addr) {
            rewind_inst.p2 = close_addr as i64;
        }

        Ok(())
    }

    /// Compile a table scan with LIMIT/OFFSET and function expressions
    fn compile_table_scan_with_limit(
        &mut self,
        select: &Select,
        query: &Query,
        table_name: &str,
    ) -> SqawkResult<()> {
        let table = self.database.get_table(table_name).unwrap();
        let projection = &select.projection;

        // Build result schema with column names and types
        let schema = self.build_result_schema(projection, table);
        self.program.set_result_schema(schema);

        let (limit_val, offset_val) = self.extract_limit_offset(query)?;

        let cursor_idx = 0i64;

        // Open table
        self.emit(
            OpCode::OpenRead,
            cursor_idx,
            1,
            0,
            Some(table_name.to_string()),
            &format!("Open table {} for reading", table_name),
        );

        // Initialize limit counter
        let limit_reg = if let Some(limit) = limit_val {
            let reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                limit,
                reg,
                0,
                None,
                "Initialize limit counter",
            );
            Some(reg)
        } else {
            None
        };

        // Initialize offset counter
        let offset_reg = if offset_val > 0 {
            let reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                offset_val,
                reg,
                0,
                None,
                "Initialize offset counter",
            );
            Some(reg)
        } else {
            None
        };

        // Rewind
        let rewind_addr = self.program.len();
        self.emit(OpCode::Rewind, cursor_idx, 0, 0, None, "Rewind cursor");

        let loop_start = self.program.len();

        // Pre-allocate result registers to ensure they are contiguous
        let mut result_regs = Vec::new();
        for _ in projection {
            let value_reg = self.allocate_register();
            result_regs.push(value_reg);
        }

        // Load projection values into registers with function support
        for (idx, item) in projection.iter().enumerate() {
            let value_reg = result_regs[idx];

            match item {
                // Multiple aliases for one item (`expr AS (a, b)`) is a
                // non-standard extension sqawk does not implement.
                SelectItem::ExprWithAliases { .. } => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Multiple column aliases are not supported".into(),
                    ))
                }
                SelectItem::Wildcard(_) | SelectItem::QualifiedWildcard(_, _) => {
                    for col_idx in 0..table.column_count() {
                        if col_idx > 0 {
                            let extra_reg = self.allocate_register();
                            result_regs.push(extra_reg);
                            self.emit(
                                OpCode::Column,
                                cursor_idx,
                                col_idx as i64,
                                extra_reg,
                                None,
                                &format!("r[{}] = column {}", extra_reg, col_idx),
                            );
                        } else {
                            self.emit(
                                OpCode::Column,
                                cursor_idx,
                                0,
                                value_reg,
                                None,
                                &format!("r[{}] = column 0", value_reg),
                            );
                        }
                    }
                }
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. } => {
                    self.compile_projection_expr(expr, table, cursor_idx as usize, value_reg)?;
                }
            }
        }

        // WHERE clause
        if let Some(where_expr) = &select.selection {
            let cond_reg = self.compile_where_condition(where_expr, table, cursor_idx as usize)?;
            // Jump to Next if condition fails
            let next_addr = self.program.len()
                + 1
                + if offset_reg.is_some() { 2 } else { 0 }
                + if limit_reg.is_some() { 2 } else { 0 }
                + 1; // ResultRow
            self.emit(
                OpCode::IfZ,
                cond_reg,
                next_addr as i64,
                0,
                None,
                "Skip if WHERE false",
            );
        }

        // Handle offset
        if let Some(offset_r) = offset_reg {
            // If offset counter > 0, decrement and skip this row
            let after_skip = self.program.len() + 2;
            self.emit(
                OpCode::DecrJumpZero,
                offset_r,
                after_skip as i64,
                0,
                None,
                "Decrement offset, skip if done",
            );
            // Jump to next row (skip output)
            let next_addr = self.program.len() + if limit_reg.is_some() { 3 } else { 1 } + 1;
            self.emit(
                OpCode::Goto,
                0,
                next_addr as i64,
                0,
                None,
                "Skip row for offset",
            );
        }

        // Output result row
        self.emit(
            OpCode::ResultRow,
            result_regs[0],
            result_regs.len() as i64,
            0,
            None,
            "Output result row",
        );

        // Handle limit
        if let Some(limit_r) = limit_reg {
            // Decrement limit counter, stop if zero
            let loop_end = self.program.len() + 2;
            self.emit(
                OpCode::DecrJumpZero,
                limit_r,
                loop_end as i64,
                0,
                None,
                "Decrement limit, stop if zero",
            );
        }

        // Next row
        self.emit(
            OpCode::Next,
            cursor_idx,
            loop_start as i64,
            0,
            None,
            "Next row",
        );

        let loop_end = self.program.len();

        // Close cursor
        self.emit(OpCode::Close, cursor_idx, 0, 0, None, "Close cursor");

        // Patch rewind jump
        if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
            inst.p2 = loop_end as i64;
        }

        Ok(())
    }

    /// Compile a projection expression (column or function) into a register
    fn compile_projection_expr(
        &mut self,
        expr: &Expr,
        table: &Table,
        cursor_idx: usize,
        dest_reg: i64,
    ) -> SqawkResult<()> {
        // Delegate to the single expression compiler.
        //
        // This function used to be a parallel implementation that understood
        // only bare columns and a fixed list of single-argument functions.
        // Its `_` arm tried resolve_column_expr and, on failure, emitted NO
        // INSTRUCTION AT ALL -- leaving the destination register at its
        // default NULL. That is why `SELECT name, salary*2 FROM employees
        // LIMIT 3` produced NULLs while the same query without LIMIT (which
        // took a different path) produced correct values.
        let ctx = NameCtx::single(table, cursor_idx as i64);
        self.code_expr(expr, &ctx, Some(dest_reg)).map(|_| ())
    }

    /// Compile a WHERE condition and return the register containing the result
    pub(crate) fn compile_where_condition(
        &mut self,
        where_expr: &Expr,
        table: &Table,
        cursor_idx: usize,
    ) -> SqawkResult<i64> {
        match where_expr {
            Expr::BinaryOp { left, op, right } => {
                self.compile_binary_comparison(left, op, right, table, cursor_idx)
            }
            Expr::Like {
                negated,
                expr,
                pattern,
                ..
            } => self.compile_like_pattern(expr, pattern, *negated, table, cursor_idx, false),
            Expr::ILike {
                negated,
                expr,
                pattern,
                ..
            } => self.compile_like_pattern(expr, pattern, *negated, table, cursor_idx, true),
            Expr::Between {
                expr,
                negated,
                low,
                high,
            } => self.compile_between(expr, low, high, *negated, table, cursor_idx),
            Expr::InList {
                expr,
                list,
                negated,
            } => self.compile_in_list(expr, list, *negated, table, cursor_idx),
            Expr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => self.compile_case(
                operand.as_deref(),
                conditions,
                else_result.as_deref(),
                table,
                cursor_idx,
                None,
            ),
            Expr::IsNull(expr) => {
                // Compile IS NULL as a condition
                let expr_reg = self.allocate_register();
                let result_reg = self.allocate_register();

                self.compile_where_operand(expr, table, cursor_idx, expr_reg)?;

                self.emit(
                    OpCode::IsNull,
                    expr_reg,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = (r[{}] IS NULL)", result_reg, expr_reg),
                );

                Ok(result_reg)
            }
            Expr::IsNotNull(expr) => {
                // Compile IS NOT NULL as a condition
                let expr_reg = self.allocate_register();
                let result_reg = self.allocate_register();

                self.compile_where_operand(expr, table, cursor_idx, expr_reg)?;

                // First check IS NULL
                self.emit(
                    OpCode::IsNull,
                    expr_reg,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = (r[{}] IS NULL)", result_reg, expr_reg),
                );

                // Then negate the result (if is_null is 1, set to 0; if 0, set to 1)
                // We can do this with: result = 1 - result
                let one_reg = self.allocate_register();
                let final_reg = self.allocate_register();

                self.emit(
                    OpCode::Integer,
                    1,
                    one_reg,
                    0,
                    None,
                    &format!("r[{}] = 1", one_reg),
                );

                // Subtract using: if result is 0, final = 1; if result is 1, final = 0
                // We need a subtraction operation, but we don't have one yet
                // Alternative: use IfZ to branch
                let is_null_label = self.program.len();
                self.emit(
                    OpCode::IfZ,
                    result_reg,
                    0, // Will be patched
                    0,
                    None,
                    "if IS NULL result is 0 (not null), jump",
                );

                // result_reg was 1 (is null), so set final to 0
                self.emit(
                    OpCode::Integer,
                    0,
                    final_reg,
                    0,
                    None,
                    &format!("r[{}] = 0 (was null)", final_reg),
                );

                let skip_else_addr = self.program.len();
                self.emit(
                    OpCode::Goto,
                    0,
                    0, // Will be patched
                    0,
                    None,
                    "skip else branch",
                );

                // Patch the IfZ to jump here when result was 0 (not null)
                let not_null_label = self.program.len();
                if let Some(inst) = self.program.instructions.get_mut(is_null_label) {
                    inst.p2 = not_null_label as i64;
                }

                // result_reg was 0 (not null), so set final to 1
                self.emit(
                    OpCode::Integer,
                    1,
                    final_reg,
                    0,
                    None,
                    &format!("r[{}] = 1 (was not null)", final_reg),
                );

                // Patch skip_else to jump here
                let end_label = self.program.len();
                if let Some(inst) = self.program.instructions.get_mut(skip_else_addr) {
                    inst.p2 = end_label as i64;
                }

                Ok(final_reg)
            }
            // Phase 4F: Subquery support
            Expr::Subquery(subquery) => {
                // Scalar subquery - returns a single value
                self.compile_scalar_subquery(subquery, table, cursor_idx)
            }
            Expr::InSubquery {
                expr,
                subquery,
                negated,
            } => {
                // IN (SELECT ...) - check if value exists in subquery results
                self.compile_in_subquery(expr, subquery, *negated, table, cursor_idx)
            }
            Expr::Exists { subquery, negated } => {
                // EXISTS (SELECT ...) - check if subquery returns any rows
                self.compile_exists_subquery(subquery, *negated, table, cursor_idx)
            }
            // `NOT <predicate>`. Previously unsupported in any position: the
            // predicate compiler had no arm, and the several NOT-forms that
            // did work (NOT LIKE, NOT IN, IS NOT NULL) each hand-rolled their
            // own inversion instead of sharing one.
            Expr::UnaryOp {
                op: UnaryOperator::Not,
                expr: inner,
            } => {
                let inner_reg = self.compile_where_condition(inner, table, cursor_idx)?;
                let dest = self.allocate_register();
                self.emit(
                    OpCode::Not,
                    inner_reg,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = NOT r[{}]", dest, inner_reg),
                );
                Ok(dest)
            }
            Expr::Nested(inner) => self.compile_where_condition(inner, table, cursor_idx),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported WHERE clause expression: {:?}",
                where_expr
            ))),
        }
    }

    /// Compile a scalar subquery (Phase 4F/4B)
    ///
    /// Scalar subqueries return a single value that can be used in expressions.
    /// - Non-correlated: uses compile-time execution
    /// - Correlated: uses runtime execution with coroutines
    ///
    /// Example: SELECT * FROM users WHERE age = (SELECT MAX(age) FROM users)
    fn compile_scalar_subquery(
        &mut self,
        subquery: &Query,
        outer_table: &Table,
        outer_cursor_idx: usize,
    ) -> SqawkResult<i64> {
        let result_reg = self.allocate_register();

        // Detect if this is a correlated subquery
        let outer_refs = self.detect_outer_references(subquery, outer_table.name(), None);

        if outer_refs.is_empty() {
            // Non-correlated: evaluate at compile time
            let result_value = self.evaluate_scalar_subquery(subquery)?;
            self.emit_value_literal(result_reg, &result_value)?;
        } else {
            // Correlated: emit runtime execution bytecode
            self.compile_correlated_scalar_subquery(
                subquery,
                outer_table,
                outer_cursor_idx,
                &outer_refs,
                result_reg,
            )?;
        }

        Ok(result_reg)
    }

    /// Extract the column index from an aggregate function argument
    fn extract_agg_column_index(&self, func: &Function, table: &Table) -> SqawkResult<usize> {
        // Handle COUNT(*) specially
        if !func_args(func).is_empty() {
            match &func_args(func)[0] {
                FunctionArg::Unnamed(FunctionArgExpr::Wildcard) => {
                    // COUNT(*) - use first column (doesn't matter which for count)
                    return Ok(0);
                }
                FunctionArg::Unnamed(FunctionArgExpr::Expr(Expr::Identifier(ident))) => {
                    let col_name = ident.value.to_lowercase();
                    return table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name));
                }
                _ => {}
            }
        }
        // Default to first column
        Ok(0)
    }

    /// Emit bytecode to load a value as a literal
    fn emit_value_literal(&mut self, reg: i64, value: &TableValue) -> SqawkResult<()> {
        match value {
            TableValue::Integer(i) => {
                self.emit(
                    OpCode::Integer,
                    *i,
                    reg,
                    0,
                    None,
                    &format!("r[{}] = {} (subquery result)", reg, i),
                );
            }
            TableValue::Float(f) => {
                // Store float as string and use String opcode, then cast
                self.emit(
                    OpCode::String,
                    0,
                    reg,
                    0,
                    Some(f.to_string()),
                    &format!("r[{}] = {} (subquery result)", reg, f),
                );
                // Cast to float
                self.emit(
                    OpCode::Cast,
                    reg,
                    reg,
                    0,
                    Some("REAL".to_string()),
                    &format!("Cast r[{}] to REAL", reg),
                );
            }
            TableValue::String(s) => {
                self.emit(
                    OpCode::String,
                    0,
                    reg,
                    0,
                    Some(s.clone().into_owned()),
                    &format!("r[{}] = '{}' (subquery result)", reg, s),
                );
            }
            TableValue::Boolean(b) => {
                self.emit(
                    OpCode::Integer,
                    if *b { 1 } else { 0 },
                    reg,
                    0,
                    None,
                    &format!("r[{}] = {} (subquery result)", reg, b),
                );
            }
            TableValue::Null => {
                self.emit(
                    OpCode::Null,
                    0,
                    reg,
                    0,
                    None,
                    &format!("r[{}] = NULL (subquery result)", reg),
                );
            }
        }
        Ok(())
    }

    /// Evaluate a scalar subquery at compile time and return the result value
    /// This is used when a subquery appears as an operand in a comparison
    fn evaluate_scalar_subquery(&self, subquery: &Query) -> SqawkResult<TableValue> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "Subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the table name
        let table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in subqueries".to_string(),
                ))
            }
        };

        // Get the table
        if !self.database.has_table(&table_name) {
            return Err(SqawkError::TableNotFound(table_name.clone()));
        }
        let table = self.database.get_table(&table_name).unwrap();

        // Filter rows if there's a WHERE clause in the subquery
        let filtered_rows: Vec<&Vec<TableValue>> = if let Some(where_expr) = &select.selection {
            table
                .rows()
                .iter()
                .filter(|row| self.evaluate_where_at_compile_time(where_expr, row, table))
                .collect()
        } else {
            table.rows().iter().collect()
        };

        // Check the projection to determine what value to compute
        if select.projection.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "Subquery must have a projection".to_string(),
            ));
        }

        let result_value = match &select.projection[0] {
            SelectItem::UnnamedExpr(expr) => match expr {
                Expr::Function(func) => {
                    // Handle aggregate functions (MAX, MIN, COUNT, SUM, AVG)
                    let func_name = func
                        .name
                        .0
                        .first()
                        .map(|id| {
                            id.as_ident()
                                .map(|i| i.value.to_uppercase())
                                .unwrap_or_default()
                        })
                        .unwrap_or_default();

                    // Get the aggregate function
                    let agg_func = AggregateFunction::from_name(&func_name).ok_or_else(|| {
                        SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported aggregate function in subquery: {}",
                            func_name
                        ))
                    })?;

                    // Extract the column index from the function argument
                    let col_idx = self.extract_agg_column_index(func, table)?;

                    // Collect all values from that column
                    let values: Vec<TableValue> = filtered_rows
                        .iter()
                        .map(|row| row[col_idx].clone())
                        .collect();

                    // Execute the aggregate function
                    agg_func.execute(&values)?
                }
                Expr::Identifier(ident) => {
                    // Simple column reference - get first row's value
                    let col_name = ident.value.to_lowercase();
                    let col_idx = table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name.clone()))?;

                    if filtered_rows.is_empty() {
                        TableValue::Null
                    } else {
                        filtered_rows[0][col_idx].clone()
                    }
                }
                _ => {
                    // Default: get first column of first row
                    if filtered_rows.is_empty() {
                        TableValue::Null
                    } else {
                        filtered_rows[0][0].clone()
                    }
                }
            },
            SelectItem::Wildcard(_) => {
                // SELECT * - just get first column of first row
                if filtered_rows.is_empty() {
                    TableValue::Null
                } else {
                    filtered_rows[0][0].clone()
                }
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Unsupported projection in scalar subquery".to_string(),
                ))
            }
        };

        Ok(result_value)
    }

    /// Evaluate an EXISTS subquery at compile time and return true/false
    fn evaluate_exists_subquery(&self, subquery: &Query, negated: bool) -> SqawkResult<bool> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in EXISTS clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "EXISTS subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in EXISTS subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Check if any rows match the subquery's WHERE clause
        let has_rows = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .any(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
        } else {
            !subquery_table.rows().is_empty()
        };

        Ok(if negated { !has_rows } else { has_rows })
    }

    /// Evaluate an IN subquery at compile time and return the list of values
    fn evaluate_in_subquery_values(&self, subquery: &Query) -> SqawkResult<Vec<TableValue>> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in IN clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "IN subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in IN subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Filter rows if there's a WHERE clause in the subquery
        let filtered_rows: Vec<&Vec<TableValue>> = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .filter(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
                .collect()
        } else {
            subquery_table.rows().iter().collect()
        };

        // Get the column index from the subquery projection
        let col_idx = if select.projection.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "IN subquery must have a projection".to_string(),
            ));
        } else {
            match &select.projection[0] {
                SelectItem::UnnamedExpr(Expr::Identifier(ident)) => {
                    let col_name = ident.value.to_lowercase();
                    subquery_table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name))?
                }
                SelectItem::Wildcard(_) => 0,
                _ => 0, // Default to first column
            }
        };

        // Collect values from the subquery result
        let values: Vec<TableValue> = filtered_rows
            .iter()
            .map(|row| row[col_idx].clone())
            .collect();

        Ok(values)
    }

    /// Evaluate a WHERE expression at compile time for subquery filtering
    fn evaluate_where_at_compile_time(
        &self,
        expr: &Expr,
        row: &[TableValue],
        table: &Table,
    ) -> bool {
        match expr {
            Expr::BinaryOp { left, op, right } => {
                match op {
                    BinaryOperator::And => {
                        self.evaluate_where_at_compile_time(left, row, table)
                            && self.evaluate_where_at_compile_time(right, row, table)
                    }
                    BinaryOperator::Or => {
                        self.evaluate_where_at_compile_time(left, row, table)
                            || self.evaluate_where_at_compile_time(right, row, table)
                    }
                    BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq => {
                        let left_val = self.evaluate_expr_at_compile_time(left, row, table);
                        let right_val = self.evaluate_expr_at_compile_time(right, row, table);
                        self.compare_values(&left_val, &right_val, op)
                    }
                    _ => true, // Unknown op, assume true
                }
            }
            Expr::IsNull(inner) => {
                let val = self.evaluate_expr_at_compile_time(inner, row, table);
                matches!(val, TableValue::Null)
            }
            Expr::IsNotNull(inner) => {
                let val = self.evaluate_expr_at_compile_time(inner, row, table);
                !matches!(val, TableValue::Null)
            }
            _ => true, // Unknown expression, assume true
        }
    }

    /// Evaluate an expression at compile time to get a value
    fn evaluate_expr_at_compile_time(
        &self,
        expr: &Expr,
        row: &[TableValue],
        table: &Table,
    ) -> TableValue {
        match expr {
            Expr::Identifier(ident) => {
                let col_name = ident.value.to_lowercase();
                if let Some(idx) = table.column_index(&col_name) {
                    row[idx].clone()
                } else {
                    TableValue::Null
                }
            }
            Expr::Value(ValueWithSpan { value: val, .. }) => match val {
                Value::Number(n, _) => {
                    if let Ok(i) = n.parse::<i64>() {
                        TableValue::Integer(i)
                    } else if let Ok(f) = n.parse::<f64>() {
                        TableValue::Float(f)
                    } else {
                        TableValue::String(n.clone().into())
                    }
                }
                Value::SingleQuotedString(s) | Value::DoubleQuotedString(s) => {
                    TableValue::String(s.clone().into())
                }
                Value::Boolean(b) => TableValue::Boolean(*b),
                Value::Null => TableValue::Null,
                _ => TableValue::Null,
            },
            _ => TableValue::Null,
        }
    }

    /// Compare two values using the given operator
    fn compare_values(&self, left: &TableValue, right: &TableValue, op: &BinaryOperator) -> bool {
        match (left, right) {
            (TableValue::Integer(l), TableValue::Integer(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Float(l), TableValue::Float(r)) => match op {
                BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Integer(l), TableValue::Float(r)) => {
                let l = *l as f64;
                match op {
                    BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                    BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                    BinaryOperator::Lt => l < *r,
                    BinaryOperator::LtEq => l <= *r,
                    BinaryOperator::Gt => l > *r,
                    BinaryOperator::GtEq => l >= *r,
                    _ => false,
                }
            }
            (TableValue::Float(l), TableValue::Integer(r)) => {
                let r = *r as f64;
                match op {
                    BinaryOperator::Eq => (l - r).abs() < f64::EPSILON,
                    BinaryOperator::NotEq => (l - r).abs() >= f64::EPSILON,
                    BinaryOperator::Lt => *l < r,
                    BinaryOperator::LtEq => *l <= r,
                    BinaryOperator::Gt => *l > r,
                    BinaryOperator::GtEq => *l >= r,
                    _ => false,
                }
            }
            (TableValue::String(l), TableValue::String(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                BinaryOperator::Lt => l < r,
                BinaryOperator::LtEq => l <= r,
                BinaryOperator::Gt => l > r,
                BinaryOperator::GtEq => l >= r,
                _ => false,
            },
            (TableValue::Boolean(l), TableValue::Boolean(r)) => match op {
                BinaryOperator::Eq => l == r,
                BinaryOperator::NotEq => l != r,
                _ => false,
            },
            // Handle string to number comparisons
            (TableValue::String(s), TableValue::Integer(i)) => {
                if let Ok(n) = s.parse::<i64>() {
                    match op {
                        BinaryOperator::Eq => n == *i,
                        BinaryOperator::NotEq => n != *i,
                        BinaryOperator::Lt => n < *i,
                        BinaryOperator::LtEq => n <= *i,
                        BinaryOperator::Gt => n > *i,
                        BinaryOperator::GtEq => n >= *i,
                        _ => false,
                    }
                } else {
                    false
                }
            }
            (TableValue::Integer(i), TableValue::String(s)) => {
                if let Ok(n) = s.parse::<i64>() {
                    match op {
                        BinaryOperator::Eq => *i == n,
                        BinaryOperator::NotEq => *i != n,
                        BinaryOperator::Lt => *i < n,
                        BinaryOperator::LtEq => *i <= n,
                        BinaryOperator::Gt => *i > n,
                        BinaryOperator::GtEq => *i >= n,
                        _ => false,
                    }
                } else {
                    false
                }
            }
            _ => false, // NULL comparisons return false
        }
    }

    /// Compile an IN (SELECT ...) subquery (Phase 4F)
    ///
    /// Uses compile-time execution: executes the subquery during compilation
    /// and generates comparison code similar to IN (list).
    ///
    /// Example: SELECT * FROM orders WHERE user_id IN (SELECT id FROM users WHERE active = 1)
    fn compile_in_subquery(
        &mut self,
        expr: &Expr,
        subquery: &Query,
        negated: bool,
        table: &Table,
        cursor_idx: usize,
    ) -> SqawkResult<i64> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in IN clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "IN subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in IN subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Filter rows if there's a WHERE clause in the subquery
        let filtered_rows: Vec<&Vec<TableValue>> = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .filter(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
                .collect()
        } else {
            subquery_table.rows().iter().collect()
        };

        // Get the column index from the subquery projection
        let col_idx = if select.projection.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "IN subquery must have a projection".to_string(),
            ));
        } else {
            match &select.projection[0] {
                SelectItem::UnnamedExpr(Expr::Identifier(ident)) => {
                    let col_name = ident.value.to_lowercase();
                    subquery_table
                        .column_index(&col_name)
                        .ok_or(SqawkError::ColumnNotFound(col_name))?
                }
                SelectItem::Wildcard(_) => 0,
                _ => 0, // Default to first column
            }
        };

        // Collect values from the subquery result
        let subquery_values: Vec<TableValue> = filtered_rows
            .iter()
            .map(|row| row[col_idx].clone())
            .collect();

        // If subquery returns no values, handle specially
        if subquery_values.is_empty() {
            let result_reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                if negated { 1 } else { 0 },
                result_reg,
                0,
                None,
                &format!(
                    "r[{}] = {} (empty IN subquery)",
                    result_reg,
                    if negated { 1 } else { 0 }
                ),
            );
            return Ok(result_reg);
        }

        // Allocate registers
        let expr_reg = self.allocate_register();
        let result_reg = self.allocate_register();
        let temp_reg = self.allocate_register();

        // Compile the expression value (from the outer query)
        self.compile_where_operand(expr, table, cursor_idx, expr_reg)?;

        // Initialize result to 0 (false, not found)
        self.emit(
            OpCode::Integer,
            0,
            result_reg,
            0,
            None,
            &format!("r[{}] = 0 (IN subquery initial)", result_reg),
        );

        // Track jump addresses that need to be patched to skip to end when match found
        let mut jump_to_end_addrs = Vec::with_capacity(subquery_values.len());

        // Compare against each value from the subquery
        for value in &subquery_values {
            let item_reg = self.allocate_register();

            // Emit the subquery value as a literal
            self.emit_value_literal(item_reg, value)?;

            // Compare expr == item
            self.emit(
                OpCode::Eq,
                expr_reg,
                item_reg,
                temp_reg,
                None,
                &format!("r[{}] = (r[{}] == r[{}])", temp_reg, expr_reg, item_reg),
            );

            // If match found (temp_reg != 0), set result to 1 and jump to end
            let skip_set_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                temp_reg,
                0, // Will be patched to skip the next instructions
                0,
                None,
                "if no match, skip to next item",
            );

            // Set result to 1 (found)
            self.emit(
                OpCode::Integer,
                1,
                result_reg,
                0,
                None,
                &format!("r[{}] = 1 (found in subquery)", result_reg),
            );

            // Jump to end (skip remaining comparisons)
            jump_to_end_addrs.push(self.program.len());
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to end
                0,
                None,
                "skip to end",
            );

            // Patch the skip address to continue to next comparison
            let continue_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_set_addr) {
                inst.p2 = continue_addr as i64;
            }
        }

        // End label - all "found" jumps come here
        let end_label = self.program.len();

        // Patch all jump-to-end addresses
        for addr in jump_to_end_addrs {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = end_label as i64;
            }
        }

        // Handle negation: if NOT IN, invert the result
        if negated {
            let zero_reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                0,
                zero_reg,
                0,
                None,
                &format!("r[{}] = 0 for NOT IN", zero_reg),
            );
            self.emit(
                OpCode::Eq,
                result_reg,
                zero_reg,
                result_reg,
                None,
                &format!("r[{}] = (r[{}] == 0) for NOT IN", result_reg, result_reg),
            );
        }

        Ok(result_reg)
    }

    /// Compile an EXISTS (SELECT ...) subquery (Phase 4F/4B)
    ///
    /// - Non-correlated: uses compile-time execution
    /// - Correlated: uses runtime execution with inline subquery iteration
    ///
    /// Example: SELECT * FROM users WHERE EXISTS (SELECT 1 FROM orders WHERE orders.user_id = users.id)
    fn compile_exists_subquery(
        &mut self,
        subquery: &Query,
        negated: bool,
        outer_table: &Table,
        outer_cursor_idx: usize,
    ) -> SqawkResult<i64> {
        let result_reg = self.allocate_register();

        // Detect if this is a correlated subquery
        let outer_refs = self.detect_outer_references(subquery, outer_table.name(), None);

        if !outer_refs.is_empty() {
            // Correlated: emit runtime execution bytecode
            return self.compile_correlated_exists_subquery(
                subquery,
                negated,
                outer_table,
                outer_cursor_idx,
                &outer_refs,
                result_reg,
            );
        }

        // Non-correlated: use compile-time execution
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in EXISTS clause".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "EXISTS subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in EXISTS subqueries".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Check if any rows match the subquery's WHERE clause
        let has_rows = if let Some(where_expr) = &select.selection {
            subquery_table
                .rows()
                .iter()
                .any(|row| self.evaluate_where_at_compile_time(where_expr, row, subquery_table))
        } else {
            !subquery_table.rows().is_empty()
        };

        // Emit the result
        let exists = if negated { !has_rows } else { has_rows };
        self.emit(
            OpCode::Integer,
            if exists { 1 } else { 0 },
            result_reg,
            0,
            None,
            &format!(
                "r[{}] = {} ({}EXISTS result)",
                result_reg,
                if exists { 1 } else { 0 },
                if negated { "NOT " } else { "" }
            ),
        );

        Ok(result_reg)
    }

    // =========================================================================
    // Phase 4B: Correlated Subquery Support
    // =========================================================================

    /// Detect if a subquery references outer query columns (making it correlated)
    ///
    /// A correlated subquery contains references to columns from the outer query,
    /// like: SELECT * FROM orders o WHERE amount > (SELECT AVG(amount) FROM orders WHERE user_id = o.user_id)
    /// Here, `o.user_id` is an outer reference.
    fn detect_outer_references(
        &self,
        subquery: &Query,
        outer_table_name: &str,
        outer_alias: Option<&str>,
    ) -> Vec<OuterColumnRef> {
        let mut outer_refs = Vec::new();

        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => return outer_refs,
        };

        // Get the subquery's table name to distinguish from outer refs
        let subquery_table_name = select.from.first().and_then(|f| match &f.relation {
            sqlparser::ast::TableFactor::Table { name, alias, .. } => {
                let table_name = name
                    .0
                    .last()
                    .and_then(|p| p.as_ident())
                    .map(|i| i.value.to_lowercase())
                    .unwrap_or_default();
                let alias_name = alias.as_ref().map(|a| a.name.value.to_lowercase());
                Some((table_name, alias_name))
            }
            _ => None,
        });

        // Use the passed outer_alias, or fall back to self.current_outer_alias
        let effective_outer_alias = outer_alias.or(self.current_outer_alias.as_deref());

        // Walk the subquery's WHERE clause looking for outer references
        if let Some(where_expr) = &select.selection {
            self.collect_outer_refs_from_expr(
                where_expr,
                outer_table_name,
                effective_outer_alias,
                subquery_table_name.as_ref(),
                &mut outer_refs,
            );
        }

        outer_refs
    }

    /// Recursively collect outer column references from an expression
    fn collect_outer_refs_from_expr(
        &self,
        expr: &Expr,
        outer_table_name: &str,
        outer_alias: Option<&str>,
        subquery_table: Option<&(String, Option<String>)>,
        refs: &mut Vec<OuterColumnRef>,
    ) {
        match expr {
            Expr::CompoundIdentifier(parts) if parts.len() == 2 => {
                let qualifier = parts[0].value.to_lowercase();

                // Check if this references the outer table (not the subquery's own table)
                let is_outer_ref = {
                    let matches_outer_alias = outer_alias
                        .map(|a| a.to_lowercase() == qualifier)
                        .unwrap_or(false);
                    let matches_outer_table = outer_table_name.to_lowercase() == qualifier;

                    // Make sure it's not referencing the subquery's own table
                    let matches_subquery = subquery_table
                        .map(|(name, alias)| {
                            name == &qualifier
                                || alias.as_ref().map(|a| a == &qualifier).unwrap_or(false)
                        })
                        .unwrap_or(false);

                    (matches_outer_alias || matches_outer_table) && !matches_subquery
                };

                if is_outer_ref {
                    refs.push(OuterColumnRef { qualifier });
                }
            }
            Expr::BinaryOp { left, right, .. } => {
                self.collect_outer_refs_from_expr(
                    left,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
                self.collect_outer_refs_from_expr(
                    right,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
            }
            Expr::Nested(inner) => {
                self.collect_outer_refs_from_expr(
                    inner,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
            }
            Expr::UnaryOp { expr, .. } => {
                self.collect_outer_refs_from_expr(
                    expr,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
            }
            Expr::IsNull(inner) | Expr::IsNotNull(inner) => {
                self.collect_outer_refs_from_expr(
                    inner,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
            }
            Expr::Between {
                expr,
                low,
                high,
                negated: _,
            } => {
                self.collect_outer_refs_from_expr(
                    expr,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
                self.collect_outer_refs_from_expr(
                    low,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
                self.collect_outer_refs_from_expr(
                    high,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
            }
            Expr::InList { expr, list, .. } => {
                self.collect_outer_refs_from_expr(
                    expr,
                    outer_table_name,
                    outer_alias,
                    subquery_table,
                    refs,
                );
                for item in list {
                    self.collect_outer_refs_from_expr(
                        item,
                        outer_table_name,
                        outer_alias,
                        subquery_table,
                        refs,
                    );
                }
            }
            Expr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                if let Some(op) = operand {
                    self.collect_outer_refs_from_expr(
                        op,
                        outer_table_name,
                        outer_alias,
                        subquery_table,
                        refs,
                    );
                }
                for branch in conditions {
                    self.collect_outer_refs_from_expr(
                        &branch.condition,
                        outer_table_name,
                        outer_alias,
                        subquery_table,
                        refs,
                    );
                    self.collect_outer_refs_from_expr(
                        &branch.result,
                        outer_table_name,
                        outer_alias,
                        subquery_table,
                        refs,
                    );
                }
                if let Some(else_r) = else_result {
                    self.collect_outer_refs_from_expr(
                        else_r,
                        outer_table_name,
                        outer_alias,
                        subquery_table,
                        refs,
                    );
                }
            }
            Expr::Function(func) => {
                for arg in func_args(func) {
                    if let FunctionArg::Unnamed(FunctionArgExpr::Expr(e)) = arg {
                        self.collect_outer_refs_from_expr(
                            e,
                            outer_table_name,
                            outer_alias,
                            subquery_table,
                            refs,
                        );
                    }
                }
            }
            // Other expression types don't contain column references
            _ => {}
        }
    }

    /// Compile a correlated EXISTS subquery (Phase 4B)
    ///
    /// For each outer row, iterates through the subquery table and checks
    /// if any row matches the correlated condition.
    fn compile_correlated_exists_subquery(
        &mut self,
        subquery: &Query,
        negated: bool,
        outer_table: &Table,
        outer_cursor_idx: usize,
        outer_refs: &[OuterColumnRef],
        result_reg: i64,
    ) -> SqawkResult<i64> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in correlated EXISTS".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "Correlated EXISTS subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in correlated EXISTS".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Use a unique cursor ID for the subquery (offset from outer cursor)
        let sub_cursor_idx = outer_cursor_idx + 100;

        // Initialize result to 0 (not found)
        self.emit(
            OpCode::Integer,
            0,
            result_reg,
            0,
            None,
            &format!("r[{}] = 0 (EXISTS init)", result_reg),
        );

        // Open the subquery table
        self.emit(
            OpCode::OpenRead,
            sub_cursor_idx as i64,
            0,
            0,
            Some(subquery_table_name.clone()),
            &format!("Open {} for correlated EXISTS", subquery_table_name),
        );

        // Rewind to first row (jump to done if empty)
        let rewind_addr = self.program.len();
        self.emit(
            OpCode::Rewind,
            sub_cursor_idx as i64,
            0, // Will be patched to done_addr
            0,
            None,
            "Rewind subquery cursor",
        );

        let loop_start = self.program.len();

        // For the WHERE clause, we need to evaluate the correlated condition
        // This requires comparing subquery columns with outer columns
        if let Some(where_expr) = &select.selection {
            let cmp_reg = self.allocate_register();

            // Compile the WHERE condition with both tables accessible
            // For correlated subqueries, we need to handle outer references specially
            self.compile_correlated_where(
                where_expr,
                subquery_table,
                sub_cursor_idx,
                outer_table,
                outer_cursor_idx,
                outer_refs,
                cmp_reg,
            )?;

            // If condition is false (0), jump to next row
            let skip_match_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                cmp_reg,
                0, // Will be patched to next_row
                0,
                None,
                "Skip if WHERE condition false",
            );

            // Match found! Set result to 1
            self.emit(
                OpCode::Integer,
                1,
                result_reg,
                0,
                None,
                &format!("r[{}] = 1 (EXISTS match found)", result_reg),
            );

            // Jump to done (exit early)
            let goto_done_addr = self.program.len();
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to done_addr
                0,
                None,
                "Exit early on match",
            );

            // Patch skip_match to jump here
            let next_row_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_match_addr) {
                inst.p2 = next_row_addr as i64;
            }

            // Next row
            self.emit(
                OpCode::Next,
                sub_cursor_idx as i64,
                loop_start as i64,
                0,
                None,
                "Next subquery row",
            );

            // Done label
            let done_addr = self.program.len();

            // Patch rewind to jump to done if empty
            if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
                inst.p2 = done_addr as i64;
            }

            // Patch goto_done to jump here
            if let Some(inst) = self.program.instructions.get_mut(goto_done_addr) {
                inst.p2 = done_addr as i64;
            }
        } else {
            // No WHERE clause - if table has any rows, EXISTS is true
            self.emit(
                OpCode::Integer,
                1,
                result_reg,
                0,
                None,
                &format!("r[{}] = 1 (EXISTS: table has rows)", result_reg),
            );

            // Done
            let done_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
                inst.p2 = done_addr as i64;
            }
        }

        // Close the subquery cursor
        self.emit(
            OpCode::Close,
            sub_cursor_idx as i64,
            0,
            0,
            None,
            "Close subquery cursor",
        );

        // Handle NOT EXISTS: flip the result
        if negated {
            // result = (result == 0) ? 1 : 0
            // Use branching: if result is 0, set to 1; else set to 0
            let skip_zero_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                result_reg,
                0, // Will be patched
                0,
                None,
                &format!("if r[{}] == 0, jump to set 1", result_reg),
            );

            // result was non-zero (EXISTS found rows), so NOT EXISTS = 0
            self.emit(
                OpCode::Integer,
                0,
                result_reg,
                0,
                None,
                &format!("r[{}] = 0 (NOT EXISTS false)", result_reg),
            );

            let goto_end_addr = self.program.len();
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched
                0,
                None,
                "skip to end",
            );

            // result was zero (EXISTS found no rows), so NOT EXISTS = 1
            let set_one_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_zero_addr) {
                inst.p2 = set_one_addr as i64;
            }

            self.emit(
                OpCode::Integer,
                1,
                result_reg,
                0,
                None,
                &format!("r[{}] = 1 (NOT EXISTS true)", result_reg),
            );

            // Patch goto to end
            let end_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(goto_end_addr) {
                inst.p2 = end_addr as i64;
            }
        }

        Ok(result_reg)
    }

    /// Compile a WHERE clause with correlated column references
    #[allow(clippy::too_many_arguments)]
    fn compile_correlated_where(
        &mut self,
        where_expr: &Expr,
        subquery_table: &Table,
        sub_cursor_idx: usize,
        outer_table: &Table,
        outer_cursor_idx: usize,
        outer_refs: &[OuterColumnRef],
        result_reg: i64,
    ) -> SqawkResult<()> {
        match where_expr {
            Expr::BinaryOp { left, op, right } => {
                match op {
                    BinaryOperator::And => {
                        // Compile both sides and AND them
                        let left_reg = self.allocate_register();
                        let right_reg = self.allocate_register();
                        self.compile_correlated_where(
                            left,
                            subquery_table,
                            sub_cursor_idx,
                            outer_table,
                            outer_cursor_idx,
                            outer_refs,
                            left_reg,
                        )?;
                        self.compile_correlated_where(
                            right,
                            subquery_table,
                            sub_cursor_idx,
                            outer_table,
                            outer_cursor_idx,
                            outer_refs,
                            right_reg,
                        )?;
                        // AND: result = left AND right
                        // If left is 0, result is 0; else result is right
                        let skip_addr = self.program.len();
                        self.emit(
                            OpCode::IfZ,
                            left_reg,
                            0, // Will patch to set result=0
                            0,
                            None,
                            "AND: skip if left is false",
                        );
                        // Left is true, result = right
                        self.emit(
                            OpCode::Copy,
                            right_reg,
                            result_reg,
                            0,
                            None,
                            &format!("r[{}] = r[{}] (AND right)", result_reg, right_reg),
                        );
                        let goto_end_addr = self.program.len();
                        self.emit(
                            OpCode::Goto,
                            0,
                            0, // Will patch to end
                            0,
                            None,
                            "",
                        );
                        // Left is false, result = 0
                        let false_addr = self.program.len();
                        if let Some(inst) = self.program.instructions.get_mut(skip_addr) {
                            inst.p2 = false_addr as i64;
                        }
                        self.emit(
                            OpCode::Integer,
                            0,
                            result_reg,
                            0,
                            None,
                            &format!("r[{}] = 0 (AND false)", result_reg),
                        );
                        let end_addr = self.program.len();
                        if let Some(inst) = self.program.instructions.get_mut(goto_end_addr) {
                            inst.p2 = end_addr as i64;
                        }
                        Ok(())
                    }
                    BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq => {
                        // Compile left and right operands
                        let left_reg = self.allocate_register();
                        let right_reg = self.allocate_register();

                        self.compile_correlated_operand(
                            left,
                            subquery_table,
                            sub_cursor_idx,
                            outer_table,
                            outer_cursor_idx,
                            outer_refs,
                            left_reg,
                        )?;
                        self.compile_correlated_operand(
                            right,
                            subquery_table,
                            sub_cursor_idx,
                            outer_table,
                            outer_cursor_idx,
                            outer_refs,
                            right_reg,
                        )?;

                        // Emit comparison
                        let cmp_opcode = Self::binary_op_to_comparison_opcode(op)?;

                        self.emit(
                            cmp_opcode,
                            left_reg,
                            right_reg,
                            result_reg,
                            None,
                            &format!(
                                "r[{}] = r[{}] {:?} r[{}]",
                                result_reg, left_reg, op, right_reg
                            ),
                        );
                        Ok(())
                    }
                    _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                        "Unsupported operator in correlated subquery WHERE: {:?}",
                        op
                    ))),
                }
            }
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported expression in correlated subquery WHERE: {:?}",
                where_expr
            ))),
        }
    }

    /// Compile an operand in a correlated WHERE clause
    #[allow(clippy::too_many_arguments)]
    /// Compile an operand of a correlated subquery's condition.
    ///
    /// The subquery's own tables form the inner scope and the enclosing
    /// query's the outer one, which is exactly `NameCtx`'s two-level
    /// resolution: an unqualified name binds to the subquery, and a name it
    /// does not have is looked up outward.
    ///
    /// This was a private operand compiler handling identifiers, qualified
    /// identifiers and literals, so a correlated condition could not contain
    /// arithmetic or a function call even though a plain WHERE could.
    #[allow(clippy::too_many_arguments)]
    fn compile_correlated_operand(
        &mut self,
        expr: &Expr,
        subquery_table: &Table,
        sub_cursor_idx: usize,
        outer_table: &Table,
        outer_cursor_idx: usize,
        outer_refs: &[OuterColumnRef],
        dest_reg: i64,
    ) -> SqawkResult<()> {
        // An alias the outer query used for its table must resolve too, not
        // just the table's own name.
        let outer_refname = outer_refs
            .first()
            .map(|r| r.qualifier.clone())
            .unwrap_or_else(|| outer_table.name().to_ascii_lowercase());

        let mut ctx = NameCtx::single(subquery_table, sub_cursor_idx as i64);
        ctx.outer = vec![
            Src {
                cursor: outer_cursor_idx as i64,
                reg_base: None,
                table: outer_table,
                refname: outer_refname,
            },
            Src {
                cursor: outer_cursor_idx as i64,
                reg_base: None,
                table: outer_table,
                refname: outer_table.name().to_ascii_lowercase(),
            },
        ];
        self.code_expr(expr, &ctx, Some(dest_reg)).map(|_| ())
    }

    fn compile_correlated_scalar_subquery(
        &mut self,
        subquery: &Query,
        outer_table: &Table,
        outer_cursor_idx: usize,
        outer_refs: &[OuterColumnRef],
        result_reg: i64,
    ) -> SqawkResult<()> {
        // Get the subquery's SELECT body
        let select = match &*subquery.body {
            SetExpr::Select(select) => select,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple SELECT subqueries are supported in correlated scalar".to_string(),
                ))
            }
        };

        // Verify it's a single-table query
        if select.from.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "Correlated scalar subquery must have a FROM clause".to_string(),
            ));
        }

        // Get the subquery table name
        let subquery_table_name = match &select.from[0].relation {
            sqlparser::ast::TableFactor::Table { name, .. } => self.get_table_name(name)?,
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Only simple table references are supported in correlated scalar".to_string(),
                ))
            }
        };

        // Get the subquery table
        if !self.database.has_table(&subquery_table_name) {
            return Err(SqawkError::TableNotFound(subquery_table_name.clone()));
        }
        let subquery_table = self.database.get_table(&subquery_table_name).unwrap();

        // Get the aggregate function from the SELECT list
        if select.projection.is_empty() {
            return Err(SqawkError::UnsupportedSqlFeature(
                "Correlated scalar subquery must have a SELECT expression".to_string(),
            ));
        }

        let (agg_func_name, agg_col_idx) = match &select.projection[0] {
            SelectItem::UnnamedExpr(Expr::Function(func)) => {
                let func_name = func.name.to_string().to_uppercase();
                let col_idx = self.extract_agg_column_index(func, subquery_table)?;
                (func_name, col_idx)
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "Correlated scalar subquery must select an aggregate function".to_string(),
                ))
            }
        };

        // Use a unique cursor ID for the subquery
        let sub_cursor_idx = outer_cursor_idx + 100;

        // Allocate registers for aggregate computation
        let acc_reg = self.allocate_register(); // Accumulator
        let _count_reg = self.allocate_register(); // Count for AVG (unused for now)
        let val_reg = self.allocate_register(); // Current value

        // Initialize accumulator with Null (like SQLite does)
        // AggStep/AggFinal will treat Null as "no data yet"
        self.emit(
            OpCode::Null,
            0,
            acc_reg,
            acc_reg, // P3=P2 means just set one register
            None,
            &format!("r[{}]=NULL; Init {} accumulator", acc_reg, agg_func_name),
        );

        // Validate aggregate function is supported
        match agg_func_name.as_str() {
            "COUNT" | "SUM" | "AVG" | "MIN" | "MAX" => {}
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Unsupported aggregate in correlated subquery: {}",
                    agg_func_name
                )))
            }
        }

        // Open the subquery table
        self.emit(
            OpCode::OpenRead,
            sub_cursor_idx as i64,
            0,
            0,
            Some(subquery_table_name.clone()),
            &format!("Open {} for correlated scalar", subquery_table_name),
        );

        // Rewind to first row
        let rewind_addr = self.program.len();
        self.emit(
            OpCode::Rewind,
            sub_cursor_idx as i64,
            0, // Will be patched to done_addr
            0,
            None,
            "Rewind subquery cursor",
        );

        let loop_start = self.program.len();

        // Compile WHERE condition if present
        let cmp_reg = self.allocate_register();
        let has_where = select.selection.is_some();

        if let Some(where_expr) = &select.selection {
            self.compile_correlated_where(
                where_expr,
                subquery_table,
                sub_cursor_idx,
                outer_table,
                outer_cursor_idx,
                outer_refs,
                cmp_reg,
            )?;
        }

        // If WHERE fails, skip to next row
        let skip_agg_addr = if has_where {
            let addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                cmp_reg,
                0, // Will be patched
                0,
                None,
                "Skip if WHERE false",
            );
            Some(addr)
        } else {
            None
        };

        // Load the value for aggregation
        self.emit(
            OpCode::Column,
            sub_cursor_idx as i64,
            agg_col_idx as i64,
            val_reg,
            None,
            &format!("r[{}] = subquery column for agg", val_reg),
        );

        // Update accumulator based on aggregate type
        self.emit(
            OpCode::AggStep,
            Self::agg_func_type(agg_func_name.as_str()),
            val_reg,
            acc_reg,
            None,
            &format!(
                "Aggregate step: {} r[{}] -> r[{}]",
                agg_func_name, val_reg, acc_reg
            ),
        );

        // Next row
        let next_row_addr = self.program.len();
        if let Some(skip_addr) = skip_agg_addr {
            if let Some(inst) = self.program.instructions.get_mut(skip_addr) {
                inst.p2 = next_row_addr as i64;
            }
        }

        self.emit(
            OpCode::Next,
            sub_cursor_idx as i64,
            loop_start as i64,
            0,
            None,
            "Next subquery row",
        );

        // Done - finalize aggregate
        let done_addr = self.program.len();
        if let Some(inst) = self.program.instructions.get_mut(rewind_addr) {
            inst.p2 = done_addr as i64;
        }

        // Finalize aggregate into result_reg
        // P3 = function type hint for when no AggStep was called (register still Null)
        self.emit(
            OpCode::AggFinal,
            acc_reg,
            result_reg,
            Self::agg_func_type(agg_func_name.as_str()),
            None,
            &format!("r[{}] = final {} result", result_reg, agg_func_name),
        );

        // Close the subquery cursor
        self.emit(
            OpCode::Close,
            sub_cursor_idx as i64,
            0,
            0,
            None,
            "Close subquery cursor",
        );

        Ok(())
    }

    /// Compile a LIKE/ILIKE pattern match operation
    fn compile_like_pattern(
        &mut self,
        expr: &Expr,
        pattern: &Expr,
        negated: bool,
        table: &Table,
        cursor_idx: usize,
        case_insensitive: bool,
    ) -> SqawkResult<i64> {
        // Allocate registers for the value and result
        let value_reg = self.allocate_register();
        let result_reg = self.allocate_register();

        // Compile the expression (usually a column reference)
        self.compile_where_operand(expr, table, cursor_idx, value_reg)?;

        // Get the pattern string
        let pattern_str = match pattern {
            Expr::Value(ValueWithSpan {
                value: Value::SingleQuotedString(s),
                ..
            }) => s.clone(),
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(
                    "LIKE pattern must be a string literal".to_string(),
                ))
            }
        };

        // Generate the Like opcode
        // P1 = value register, P3 = result register, P4 = pattern string
        // P2 encodes: bit 0 = negated, bit 1 = case_insensitive
        let flags = (if negated { 1 } else { 0 }) | (if case_insensitive { 2 } else { 0 });

        self.emit(
            OpCode::Like,
            value_reg,
            flags,
            result_reg,
            Some(pattern_str.clone()),
            &format!(
                "r[{}] = r[{}] {}LIKE '{}'",
                result_reg,
                value_reg,
                if negated { "NOT " } else { "" },
                pattern_str
            ),
        );

        Ok(result_reg)
    }

    /// Compile a BETWEEN expression: expr BETWEEN low AND high
    ///
    /// This compiles to: (expr >= low) AND (expr <= high)
    /// Uses conditional jumps for short-circuit evaluation.
    fn compile_between(
        &mut self,
        expr: &Expr,
        low: &Expr,
        high: &Expr,
        negated: bool,
        table: &Table,
        cursor_idx: usize,
    ) -> SqawkResult<i64> {
        // Allocate registers
        let expr_reg = self.allocate_register();
        let low_reg = self.allocate_register();
        let high_reg = self.allocate_register();
        let result_reg = self.allocate_register();
        let temp_reg = self.allocate_register();

        // Compile the expression value
        self.compile_where_operand(expr, table, cursor_idx, expr_reg)?;

        // Compile the low bound
        self.compile_where_operand(low, table, cursor_idx, low_reg)?;

        // Compile the high bound
        self.compile_where_operand(high, table, cursor_idx, high_reg)?;

        // Compare expr >= low (result in temp_reg)
        self.emit(
            OpCode::Ge,
            expr_reg,
            low_reg,
            temp_reg,
            None,
            &format!("r[{}] = r[{}] >= r[{}]", temp_reg, expr_reg, low_reg),
        );

        // If expr < low, result is false (0)
        // Jump past the second comparison if first is false
        let jump_to_false = self.program.len();
        self.emit(
            OpCode::IfZ,
            temp_reg,
            0, // Will be patched
            0,
            None,
            "if first comparison false, skip to result",
        );

        // Compare expr <= high (result in result_reg)
        self.emit(
            OpCode::Le,
            expr_reg,
            high_reg,
            result_reg,
            None,
            &format!("r[{}] = r[{}] <= r[{}]", result_reg, expr_reg, high_reg),
        );

        // Jump past the "set to false" instruction
        let jump_to_end = self.program.len();
        self.emit(
            OpCode::Goto,
            0,
            0, // Will be patched
            0,
            None,
            "skip false assignment",
        );

        // Set result to 0 (false) - this is where we jump if first comparison fails
        let false_label = self.program.len();
        self.emit(
            OpCode::Integer,
            0,
            result_reg,
            0,
            None,
            &format!("r[{}] = 0 (BETWEEN false)", result_reg),
        );

        let end_label = self.program.len();

        // Patch the jump addresses
        if let Some(inst) = self.program.instructions.get_mut(jump_to_false) {
            inst.p2 = false_label as i64;
        }
        if let Some(inst) = self.program.instructions.get_mut(jump_to_end) {
            inst.p2 = end_label as i64;
        }

        // Handle negation: if NOT BETWEEN, invert the result
        // NOT BETWEEN is true when BETWEEN is false (result == 0)
        if negated {
            let zero_reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                0,
                zero_reg,
                0,
                None,
                &format!("r[{}] = 0 for NOT BETWEEN", zero_reg),
            );
            self.emit(
                OpCode::Eq,
                result_reg,
                zero_reg,
                result_reg,
                None,
                &format!(
                    "r[{}] = (r[{}] == 0) for NOT BETWEEN",
                    result_reg, result_reg
                ),
            );
        }

        Ok(result_reg)
    }

    /// Compile an IN list expression: expr IN (val1, val2, ...)
    ///
    /// This compiles to a series of equality checks with short-circuit OR logic.
    fn compile_in_list(
        &mut self,
        expr: &Expr,
        list: &[Expr],
        negated: bool,
        table: &Table,
        cursor_idx: usize,
    ) -> SqawkResult<i64> {
        if list.is_empty() {
            // Empty list: IN () is always false, NOT IN () is always true
            let result_reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                if negated { 1 } else { 0 },
                result_reg,
                0,
                None,
                &format!(
                    "r[{}] = {} (empty IN list)",
                    result_reg,
                    if negated { 1 } else { 0 }
                ),
            );
            return Ok(result_reg);
        }

        // Allocate registers
        let expr_reg = self.allocate_register();
        let result_reg = self.allocate_register();
        let temp_reg = self.allocate_register();

        // Compile the expression value
        self.compile_where_operand(expr, table, cursor_idx, expr_reg)?;

        // Initialize result to 0 (false, not found in list)
        self.emit(
            OpCode::Integer,
            0,
            result_reg,
            0,
            None,
            &format!("r[{}] = 0 (IN list initial)", result_reg),
        );

        // Track jump addresses that need to be patched to skip to end when match found
        let mut jump_to_end_addrs = Vec::new();

        // Compare against each value in the list
        for item in list {
            let item_reg = self.allocate_register();

            // Compile the list item value
            self.compile_where_operand(item, table, cursor_idx, item_reg)?;

            // Compare expr == item
            self.emit(
                OpCode::Eq,
                expr_reg,
                item_reg,
                temp_reg,
                None,
                &format!("r[{}] = (r[{}] == r[{}])", temp_reg, expr_reg, item_reg),
            );

            // If match found (temp_reg != 0), set result to 1 and jump to end
            // We use IfZ to skip setting result if no match
            let skip_set_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                temp_reg,
                0, // Will be patched to skip the next instructions
                0,
                None,
                "if no match, skip to next item",
            );

            // Set result to 1 (found)
            self.emit(
                OpCode::Integer,
                1,
                result_reg,
                0,
                None,
                &format!("r[{}] = 1 (found in list)", result_reg),
            );

            // Jump to end (skip remaining comparisons)
            jump_to_end_addrs.push(self.program.len());
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to end
                0,
                None,
                "skip to end",
            );

            // Patch the skip address to continue to next comparison
            let continue_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_set_addr) {
                inst.p2 = continue_addr as i64;
            }
        }

        // End label - all "found" jumps come here
        let end_label = self.program.len();

        // Patch all jump-to-end addresses
        for addr in jump_to_end_addrs {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = end_label as i64;
            }
        }

        // Handle negation: if NOT IN, invert the result
        if negated {
            let zero_reg = self.allocate_register();
            self.emit(
                OpCode::Integer,
                0,
                zero_reg,
                0,
                None,
                &format!("r[{}] = 0 for NOT IN", zero_reg),
            );
            self.emit(
                OpCode::Eq,
                result_reg,
                zero_reg,
                result_reg,
                None,
                &format!("r[{}] = (r[{}] == 0) for NOT IN", result_reg, result_reg),
            );
        }

        Ok(result_reg)
    }

    /// Compile a SUBSTRING/SUBSTR expression into `target_reg`.
    ///
    /// Shared by the projection and WHERE paths: `SUBSTR(x, 1, 3)` and
    /// `SUBSTRING(x FROM 1 FOR 3)` are the same `Expr::Substring` node, and
    /// both positions need to compile it identically.
    #[allow(clippy::too_many_arguments)]
    fn compile_substring(
        &mut self,
        sub_expr: &Expr,
        substring_from: Option<&Expr>,
        substring_for: Option<&Expr>,
        table: &Table,
        cursor_idx: usize,
        target_reg: i64,
    ) -> SqawkResult<()> {
        // A start position is required.
        //
        // sqlparser 0.62 parses `SUBSTR(x)` into this node with no start, and
        // defaulting it to 1 returned the whole string unchanged -- so a
        // dropped or mistyped argument silently produced untruncated output.
        // The arity check in compile_func_substr became unreachable for this
        // spelling, since SUBSTR no longer arrives as a Function call.
        if substring_from.is_none() {
            return Err(SqawkError::InvalidSqlQuery(
                "SUBSTR requires at least two arguments".to_string(),
            ));
        }

        let src_reg = self.allocate_register();
        self.compile_where_operand(sub_expr, table, cursor_idx, src_reg)?;

        // Start position defaults to 1 when omitted.
        let start_reg = self.allocate_register();
        if let Some(from_expr) = substring_from {
            self.compile_where_operand(from_expr, table, cursor_idx, start_reg)?;
        } else {
            self.emit(
                OpCode::Integer,
                1,
                start_reg,
                0,
                None,
                &format!("r[{}] = 1 (default start)", start_reg),
            );
        }

        // A length, if given, is passed to the engine via the P4 spec.
        let func_spec = if let Some(for_expr) = substring_for {
            let len_reg = self.allocate_register();
            self.compile_where_operand(for_expr, table, cursor_idx, len_reg)?;
            format!("SUBSTR:{}", len_reg)
        } else {
            "SUBSTR".to_string()
        };

        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            start_reg,
            Some(func_spec),
            &format!("r[{}] = SUBSTR(...)", target_reg),
        );
        Ok(())
    }

    /// Compile a CASE expression
    ///
    /// Supports both:
    /// - Simple CASE: CASE expr WHEN val1 THEN res1 ... ELSE default END
    /// - Searched CASE: CASE WHEN cond1 THEN res1 ... ELSE default END
    fn compile_case(
        &mut self,
        operand: Option<&Expr>,
        conditions: &[CaseWhen],
        else_result: Option<&Expr>,
        table: &Table,
        cursor_idx: usize,
        target_reg: Option<i64>,
    ) -> SqawkResult<i64> {
        let result_reg = target_reg.unwrap_or_else(|| self.allocate_register());
        let temp_reg = self.allocate_register();

        // For simple CASE, compile the operand once
        let operand_reg = if let Some(op_expr) = operand {
            let reg = self.allocate_register();
            self.compile_where_operand(op_expr, table, cursor_idx, reg)?;
            Some(reg)
        } else {
            None
        };

        // Track jump addresses that need to go to the end
        let mut jump_to_end_addrs = Vec::new();

        // Process each WHEN clause
        for CaseWhen {
            condition,
            result: result_expr,
        } in conditions.iter()
        {
            let cond_reg = self.allocate_register();

            if let Some(op_reg) = operand_reg {
                // Simple CASE: compare operand with condition value
                self.compile_where_operand(condition, table, cursor_idx, cond_reg)?;
                self.emit(
                    OpCode::Eq,
                    op_reg,
                    cond_reg,
                    temp_reg,
                    None,
                    &format!(
                        "r[{}] = (r[{}] == r[{}]) for CASE",
                        temp_reg, op_reg, cond_reg
                    ),
                );
            } else {
                // Searched CASE: evaluate condition directly
                // For now, we only support simple boolean conditions
                // The condition should evaluate to a boolean/integer result
                self.compile_where_operand(condition, table, cursor_idx, temp_reg)?;
            }

            // If condition is false (temp_reg == 0), skip to next branch
            let skip_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                temp_reg,
                0, // Will be patched
                0,
                None,
                "if WHEN condition false, try next",
            );

            // Condition is true - compile the result value into result_reg
            self.compile_where_operand(result_expr, table, cursor_idx, result_reg)?;

            // Jump to end
            jump_to_end_addrs.push(self.program.len());
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to end
                0,
                None,
                "jump to CASE end",
            );

            // Patch skip address to continue to next WHEN
            let next_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_addr) {
                inst.p2 = next_addr as i64;
            }
        }

        // ELSE clause (or NULL if no ELSE)
        if let Some(else_expr) = else_result {
            self.compile_where_operand(else_expr, table, cursor_idx, result_reg)?;
        } else {
            // No ELSE - result is NULL
            self.emit(
                OpCode::Null,
                0,
                result_reg,
                0,
                None,
                &format!("r[{}] = NULL (no ELSE in CASE)", result_reg),
            );
        }

        // End label
        let end_label = self.program.len();

        // Patch all jump-to-end addresses
        for addr in jump_to_end_addrs {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = end_label as i64;
            }
        }

        Ok(result_reg)
    }

    /// Extract function name from a Function AST node
    fn get_function_name(func: &Function) -> String {
        func.name
            .0
            .iter()
            .map(|id| id.as_ident().map(|i| i.value.as_str()).unwrap_or_default())
            .collect::<Vec<_>>()
            .join(".")
            .to_uppercase()
    }

    /// Compile COALESCE function - returns first non-NULL argument
    fn compile_func_coalesce(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(
                "COALESCE requires at least one argument".to_string(),
            ));
        }

        let mut jump_to_end_addrs = Vec::new();

        for arg in func_args(func) {
            let expr = self.extract_function_arg_expr(arg)?;
            let arg_reg = self.allocate_register();
            let null_check_reg = self.allocate_register();

            // Compile the argument
            self.code_expr_into(&expr, ctx, arg_reg)?;

            // Check if it's NULL
            self.emit(
                OpCode::IsNull,
                arg_reg,
                null_check_reg,
                0,
                None,
                &format!("r[{}] = (r[{}] IS NULL)", null_check_reg, arg_reg),
            );

            // If NULL (null_check_reg == 1), skip to next argument
            let skip_addr = self.program.len();
            self.emit(
                OpCode::IfZ,
                null_check_reg,
                0, // Will be patched to "use this value"
                0,
                None,
                "if NOT NULL, use this value",
            );

            // Patch to jump to next iteration (will be set at end of this iteration)
            let continue_to_next = self.program.len();

            // Add a goto to skip to next arg check (this arg was NULL)
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to next arg check
                0,
                None,
                "skip to next arg (this was NULL)",
            );

            // Patch the IfZ to come here when not NULL
            let use_value_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(skip_addr) {
                inst.p2 = use_value_addr as i64;
            }

            // Copy value to target register (value is not NULL)
            // Cast to same type as workaround for copy
            self.emit(
                OpCode::Cast,
                arg_reg,
                target_reg,
                0,
                Some("TEXT".to_string()),
                &format!("r[{}] = r[{}] (COALESCE result)", target_reg, arg_reg),
            );

            // Jump to end (we found a non-NULL value)
            jump_to_end_addrs.push(self.program.len());
            self.emit(
                OpCode::Goto,
                0,
                0, // Will be patched to end
                0,
                None,
                "jump to COALESCE end",
            );

            // Patch the continue_to_next goto to jump here
            let next_arg_addr = self.program.len();
            if let Some(inst) = self.program.instructions.get_mut(continue_to_next) {
                inst.p2 = next_arg_addr as i64;
            }
        }

        // If all args were NULL, result is NULL
        self.emit(
            OpCode::Null,
            0,
            target_reg,
            0,
            None,
            &format!("r[{}] = NULL (all COALESCE args were NULL)", target_reg),
        );

        // Patch all jump-to-end addresses
        let end_label = self.program.len();
        for addr in jump_to_end_addrs {
            if let Some(inst) = self.program.instructions.get_mut(addr) {
                inst.p2 = end_label as i64;
            }
        }

        Ok(())
    }

    /// Compile NULLIF function - returns NULL if both args are equal
    fn compile_func_nullif(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "NULLIF requires exactly two arguments".to_string(),
            ));
        }

        let expr1 = self.extract_function_arg_expr(&func_args(func)[0])?;
        let expr2 = self.extract_function_arg_expr(&func_args(func)[1])?;

        let reg1 = self.allocate_register();
        let reg2 = self.allocate_register();
        let cmp_reg = self.allocate_register();

        // Compile both arguments
        self.code_expr_into(&expr1, ctx, reg1)?;
        self.code_expr_into(&expr2, ctx, reg2)?;

        // Compare them
        self.emit(
            OpCode::Eq,
            reg1,
            reg2,
            cmp_reg,
            None,
            &format!("r[{}] = (r[{}] == r[{}])", cmp_reg, reg1, reg2),
        );

        // If equal (cmp_reg == 1), return NULL; else return reg1
        let not_equal_addr = self.program.len();
        self.emit(
            OpCode::IfZ,
            cmp_reg,
            0, // Will be patched
            0,
            None,
            "if NOT equal, jump",
        );

        // Values are equal, set result to NULL
        self.emit(
            OpCode::Null,
            0,
            target_reg,
            0,
            None,
            &format!("r[{}] = NULL (values equal)", target_reg),
        );

        let skip_else_addr = self.program.len();
        self.emit(
            OpCode::Goto,
            0,
            0, // Will be patched
            0,
            None,
            "skip else branch",
        );

        // Patch IfZ to jump here (values not equal)
        let else_addr = self.program.len();
        if let Some(inst) = self.program.instructions.get_mut(not_equal_addr) {
            inst.p2 = else_addr as i64;
        }

        // Values not equal, copy reg1 to target
        self.emit(
            OpCode::Cast,
            reg1,
            target_reg,
            0,
            Some("TEXT".to_string()),
            &format!("r[{}] = r[{}] (values not equal)", target_reg, reg1),
        );

        // Patch skip_else to jump here
        let end_addr = self.program.len();
        if let Some(inst) = self.program.instructions.get_mut(skip_else_addr) {
            inst.p2 = end_addr as i64;
        }

        Ok(())
    }

    /// Compile simple string functions (UPPER, LOWER, TRIM, LTRIM, RTRIM, LENGTH)
    fn compile_func_string_simple(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires one argument",
                func_name
            )));
        }

        let expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // Emit StringFunc opcode
        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
        );

        Ok(())
    }

    /// Compile SUBSTR/SUBSTRING function
    fn compile_func_substr(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() < 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "SUBSTR requires at least two arguments".to_string(),
            ));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let start_expr = self.extract_function_arg_expr(&func_args(func)[1])?;

        let str_reg = self.allocate_register();
        let start_reg = self.allocate_register();

        // Compile string and start arguments
        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&start_expr, ctx, start_reg)?;

        // Check if we have a length argument
        let func_spec = if func_args(func).len() >= 3 {
            let len_expr = self.extract_function_arg_expr(&func_args(func)[2])?;
            let len_reg = self.allocate_register();
            self.code_expr_into(&len_expr, ctx, len_reg)?;
            format!("SUBSTR:{}", len_reg)
        } else {
            "SUBSTR".to_string()
        };

        // Emit StringFunc opcode
        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            start_reg,
            Some(func_spec),
            &format!("r[{}] = SUBSTR(...)", target_reg),
        );

        Ok(())
    }

    /// Compile REPLACE function
    fn compile_func_replace(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 3 {
            return Err(SqawkError::InvalidSqlQuery(
                "REPLACE requires three arguments".to_string(),
            ));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let from_expr = self.extract_function_arg_expr(&func_args(func)[1])?;
        let to_expr = self.extract_function_arg_expr(&func_args(func)[2])?;

        let str_reg = self.allocate_register();
        let from_reg = self.allocate_register();
        let to_reg = self.allocate_register();

        // Compile all three arguments
        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&from_expr, ctx, from_reg)?;
        self.code_expr_into(&to_expr, ctx, to_reg)?;

        // Emit StringFunc opcode with from_reg and to_reg in P4
        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            0,
            Some(format!("REPLACE:{}:{}", from_reg, to_reg)),
            &format!("r[{}] = REPLACE(...)", target_reg),
        );

        Ok(())
    }

    /// Compile CONCAT function
    fn compile_func_concat(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() < 2 {
            return Err(SqawkError::InvalidSqlQuery(
                "CONCAT requires at least two arguments".to_string(),
            ));
        }

        // Compile first argument to src_reg
        let first_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();
        self.code_expr_into(&first_expr, ctx, src_reg)?;

        // Compile remaining arguments and build P4 spec
        let mut arg_regs = Vec::with_capacity(func_args(func).len().saturating_sub(1));
        for arg in func_args(func).iter().skip(1) {
            let expr = self.extract_function_arg_expr(arg)?;
            let reg = self.allocate_register();
            self.code_expr_into(&expr, ctx, reg)?;
            arg_regs.push(reg.to_string());
        }

        // P4 = "CONCAT:reg1:reg2:..."
        let func_spec = format!("CONCAT:{}", arg_regs.join(":"));

        self.emit(
            OpCode::StringFunc,
            src_reg,
            target_reg,
            0,
            Some(func_spec),
            &format!("r[{}] = CONCAT(...)", target_reg),
        );

        Ok(())
    }

    /// Compile LEFT and RIGHT string functions
    fn compile_func_left_right(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).len() != 2 {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires exactly two arguments",
                func_name
            )));
        }

        let str_expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let len_expr = self.extract_function_arg_expr(&func_args(func)[1])?;

        let str_reg = self.allocate_register();
        let len_reg = self.allocate_register();

        self.code_expr_into(&str_expr, ctx, str_reg)?;
        self.code_expr_into(&len_expr, ctx, len_reg)?;

        self.emit(
            OpCode::StringFunc,
            str_reg,
            target_reg,
            len_reg,
            Some(func_name.to_string()),
            &format!(
                "r[{}] = {}(r[{}], r[{}])",
                target_reg, func_name, str_reg, len_reg
            ),
        );

        Ok(())
    }

    /// Compile math functions (ABS, ROUND, CEIL, CEILING, FLOOR)
    fn compile_func_math(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        let args = func_args(func);
        if args.is_empty() {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires one argument",
                func_name
            )));
        }

        // ROUND is the only one of these that takes an optional second
        // argument. The others used to accept and silently drop extras.
        let max_args = if func_name == "ROUND" { 2 } else { 1 };
        if args.len() > max_args {
            return Err(SqawkError::InvalidSqlQuery(if max_args == 1 {
                format!("{} takes exactly one argument", func_name)
            } else {
                format!("{} takes at most two arguments", func_name)
            }));
        }

        let expr = self.extract_function_arg_expr(&args[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // P3 carries the register holding ROUND's precision, or -1 when the
        // call has no second argument.
        let (prec_reg, desc) = if args.len() == 2 {
            let prec_expr = self.extract_function_arg_expr(&args[1])?;
            let reg = self.allocate_register();
            self.code_expr_into(&prec_expr, ctx, reg)?;
            (
                reg,
                format!(
                    "r[{}] = {}(r[{}], r[{}])",
                    target_reg, func_name, src_reg, reg
                ),
            )
        } else {
            (
                -1,
                format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
            )
        };

        // Emit MathFunc opcode
        self.emit(
            OpCode::MathFunc,
            src_reg,
            target_reg,
            prec_reg,
            Some(func_name.to_string()),
            &desc,
        );

        Ok(())
    }

    /// Compile date/time functions with no arguments (NOW, CURRENT_TIMESTAMP, etc.)
    fn compile_func_datetime_noarg(&mut self, func_name: &str, target_reg: i64) -> SqawkResult<()> {
        self.emit(
            OpCode::DateFunc,
            0, // No source register needed
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}()", target_reg, func_name),
        );

        Ok(())
    }

    /// Compile date/time functions with one argument (DATE, TIME)
    fn compile_func_datetime(
        &mut self,
        func_name: &str,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        if func_args(func).is_empty() {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "{} requires one argument",
                func_name
            )));
        }

        let expr = self.extract_function_arg_expr(&func_args(func)[0])?;
        let src_reg = self.allocate_register();

        // Compile the argument
        self.code_expr_into(&expr, ctx, src_reg)?;

        // Emit DateFunc opcode
        self.emit(
            OpCode::DateFunc,
            src_reg,
            target_reg,
            0,
            Some(func_name.to_string()),
            &format!("r[{}] = {}(r[{}])", target_reg, func_name, src_reg),
        );

        Ok(())
    }

    /// Compile a function call - dispatches to specialized handlers
    fn compile_function(
        &mut self,
        func: &Function,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        let func_name = Self::get_function_name(func);

        match func_name.as_str() {
            "COALESCE" => self.compile_func_coalesce(func, ctx, target_reg),
            "NULLIF" => self.compile_func_nullif(func, ctx, target_reg),
            "UPPER" | "LOWER" | "TRIM" | "LTRIM" | "RTRIM" | "LENGTH" => {
                self.compile_func_string_simple(&func_name, func, ctx, target_reg)
            }
            "SUBSTR" | "SUBSTRING" => self.compile_func_substr(func, ctx, target_reg),
            "REPLACE" => self.compile_func_replace(func, ctx, target_reg),
            "CONCAT" => self.compile_func_concat(func, ctx, target_reg),
            "LEFT" | "RIGHT" => self.compile_func_left_right(&func_name, func, ctx, target_reg),
            "ABS" | "ROUND" | "CEIL" | "CEILING" | "FLOOR" => {
                self.compile_func_math(&func_name, func, ctx, target_reg)
            }
            "NOW" | "CURRENT_TIMESTAMP" | "CURRENT_DATE" | "CURRENT_TIME" => {
                self.compile_func_datetime_noarg(&func_name, target_reg)
            }
            "DATE" | "TIME" => self.compile_func_datetime(&func_name, func, ctx, target_reg),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Unsupported function: {}",
                func_name
            ))),
        }
    }

    /// Extract expression from a function argument
    pub(crate) fn extract_function_arg_expr(&self, arg: &FunctionArg) -> SqawkResult<Expr> {
        match arg {
            FunctionArg::Unnamed(FunctionArgExpr::Expr(expr)) => Ok(expr.clone()),
            FunctionArg::Named {
                arg: FunctionArgExpr::Expr(expr),
                ..
            } => Ok(expr.clone()),
            _ => Err(SqawkError::UnsupportedSqlFeature(
                "Unsupported function argument type".to_string(),
            )),
        }
    }

    /// Compile a binary comparison operation (e.g., column > value)
    fn compile_binary_comparison(
        &mut self,
        left: &Expr,
        op: &BinaryOperator,
        right: &Expr,
        table: &Table,
        cursor_idx: usize,
    ) -> SqawkResult<i64> {
        // Handle logical operators (AND, OR) specially
        match op {
            BinaryOperator::And => {
                // For AND, both conditions must be true.
                //
                // The result register MUST be initialized before the
                // short-circuit test on the left operand. Registers persist
                // across loop iterations, so if the left-false jump skips the
                // initialization, the register still holds this expression's
                // result from a PREVIOUS row -- and a row failing the left
                // condition inherits the previous row's verdict.
                let result_reg = self.allocate_register();
                self.emit(
                    OpCode::Integer,
                    0,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = 0 (default AND result)", result_reg),
                );

                let end_label = self.label();

                // Compile left condition
                let left_result = self.compile_where_condition(left, table, cursor_idx)?;

                // If left is false, the result stays 0; skip right entirely.
                self.emit_jump_to(
                    OpCode::IfZ,
                    left_result,
                    end_label,
                    0,
                    None,
                    "if left is false, AND is false",
                );

                // Compile right condition
                let right_result = self.compile_where_condition(right, table, cursor_idx)?;

                // If right is false, the result stays 0.
                self.emit_jump_to(
                    OpCode::IfZ,
                    right_result,
                    end_label,
                    0,
                    None,
                    "if right is false, AND is false",
                );

                // Both are true, set result to 1
                self.emit(
                    OpCode::Integer,
                    1,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = 1 (AND true)", result_reg),
                );

                self.resolve(end_label);
                return Ok(result_reg);
            }
            BinaryOperator::Or => {
                // For OR, at least one condition must be true
                let result_reg = self.allocate_register();

                // Initialize result to 0
                self.emit(
                    OpCode::Integer,
                    0,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = 0 (default OR result)", result_reg),
                );

                // Compile left condition
                let left_result = self.compile_where_condition(left, table, cursor_idx)?;

                // If left is true, set result to 1 and skip right
                let skip_if_left_true = self.program.len();
                self.emit(
                    OpCode::IfZ,
                    left_result,
                    0, // Will be patched to check right
                    0,
                    None,
                    "if left is false, check right",
                );

                // Left is true, set result to 1
                self.emit(
                    OpCode::Integer,
                    1,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = 1 (OR left true)", result_reg),
                );

                // Jump to end
                let goto_end = self.program.len();
                self.emit(
                    OpCode::Goto,
                    0,
                    0, // Will be patched
                    0,
                    None,
                    "goto end",
                );

                // Check right label
                let check_right_label = self.program.len();
                if let Some(inst) = self.program.instructions.get_mut(skip_if_left_true) {
                    inst.p2 = check_right_label as i64;
                }

                // Compile right condition
                let right_result = self.compile_where_condition(right, table, cursor_idx)?;

                // If right is false, skip setting result to 1
                let skip_to_end = self.program.len();
                self.emit(
                    OpCode::IfZ,
                    right_result,
                    0, // Will be patched to skip to end
                    0,
                    None,
                    "if right is false, skip to end",
                );

                // Right is true, set result to 1
                self.emit(
                    OpCode::Integer,
                    1,
                    result_reg,
                    0,
                    None,
                    &format!("r[{}] = 1 (OR right true)", result_reg),
                );

                // End label
                let end_label = self.program.len();
                if let Some(inst) = self.program.instructions.get_mut(goto_end) {
                    inst.p2 = end_label as i64;
                }
                if let Some(inst) = self.program.instructions.get_mut(skip_to_end) {
                    inst.p2 = end_label as i64;
                }

                return Ok(result_reg);
            }
            _ => {}
        }

        // Handle comparison operators
        // Allocate registers for operands and result
        let left_reg = self.allocate_register();
        let right_reg = self.allocate_register();
        let result_reg = self.allocate_register();

        // Compile left operand (usually a column reference)
        self.compile_where_operand(left, table, cursor_idx, left_reg)?;

        // Compile right operand (usually a literal value)
        self.compile_where_operand(right, table, cursor_idx, right_reg)?;

        // Generate comparison instruction based on operator
        let opcode = Self::binary_op_to_comparison_opcode(op)?;

        self.emit(
            opcode,
            left_reg,
            right_reg,
            result_reg,
            None,
            &format!(
                "r[{}] = r[{}] {:?} r[{}]",
                result_reg, left_reg, op, right_reg
            ),
        );

        Ok(result_reg)
    }

    /// Compile a WHERE clause operand (column reference or literal)
    /// Compile `expr` into a register, returning that register.
    ///
    /// This is the single expression compiler -- the analogue of SQLite's
    /// `sqlite3ExprCode()`. It is used from every position an expression can
    /// appear in, so a node supported in one position is supported in all of
    /// them. sqawk previously had two: `compile_expr` (no `Identifier` arm at
    /// all) and `compile_projection_expr`/`resolve_column_expr` ("Only column
    /// references supported in SELECT"). That split is why `CASE` and `CAST`
    /// worked in WHERE but not in a SELECT list, and why `SUBSTR` in WHERE
    /// broke on the sqlparser upgrade while `SUBSTR` in a projection did not.
    ///
    /// `into` names the destination register when the caller needs the value
    /// at a specific place -- which is how contiguous blocks for `ResultRow`
    /// and `SorterInsert` are built without the copy-shuffling the old
    /// projection paths did.
    ///
    /// Invariant: on `Ok(reg)`, code has been emitted that defines `reg` on
    /// every path. There is deliberately no arm that returns `Ok` without
    /// emitting -- that bug (an `_` arm that silently emitted nothing, leaving
    /// the register at its default NULL) is why `SELECT name, salary*2 ...
    /// LIMIT 3` returned NULL.
    pub(crate) fn code_expr(
        &mut self,
        expr: &Expr,
        ctx: &NameCtx<'_>,
        into: Option<i64>,
    ) -> SqawkResult<i64> {
        let dest = into.unwrap_or_else(|| self.allocate_register());

        match expr {
            // Column references resolve through the context, so they work
            // across joins and aliases and are matched case-insensitively.
            Expr::Identifier(ident) => {
                let col = ctx.resolve_unqualified(&ident.value)?;
                self.emit_column_ref(col, dest, &ident.value);
            }

            // `table.column` / `alias.column`. The old WHERE compiler had no
            // arm for this at all, so `FROM employees e WHERE e.age > 30`
            // failed on a single-table query.
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => {
                let qualifier = &parts[parts.len() - 2].value;
                let name = &parts[parts.len() - 1].value;
                let col = ctx.resolve_qualified(qualifier, name)?;
                self.emit_column_ref(col, dest, &format!("{}.{}", qualifier, name));
            }

            Expr::Nested(inner) => {
                return self.code_expr(inner, ctx, Some(dest));
            }

            // Literals resolve against nothing, so they are compiled here
            // rather than delegated. The fallback needs a single FROM source
            // and would otherwise reject a constant in a join condition --
            // `ON a.x = b.y AND b.id > 102` failing on the `102`.
            Expr::Value(ValueWithSpan { value, .. }) => {
                let literal = match value {
                    Value::Number(n, _) => match n.parse::<i64>() {
                        Ok(i) => TableValue::Integer(i),
                        Err(_) => match n.parse::<f64>() {
                            Ok(f) => TableValue::Float(f),
                            Err(_) => TableValue::String(n.clone().into()),
                        },
                    },
                    Value::SingleQuotedString(v) | Value::DoubleQuotedString(v) => {
                        TableValue::String(v.clone().into())
                    }
                    Value::Boolean(b) => TableValue::Boolean(*b),
                    Value::Null => TableValue::Null,
                    other => TableValue::String(other.to_string().into()),
                };
                self.emit_value_literal(dest, &literal)?;
            }

            // An aggregate call in a position where aggregates have already
            // been computed: read the bound register rather than trying to
            // compile SUM as a scalar function.
            Expr::Function(_) if ctx.lookup_agg(expr).is_some() => {
                let src = ctx.lookup_agg(expr).unwrap();
                if src != dest {
                    self.emit(
                        OpCode::Copy,
                        src,
                        dest,
                        0,
                        None,
                        &format!("r[{}] = aggregate r[{}]", dest, src),
                    );
                }
            }

            // String concatenation. sqlparser has always produced this node;
            // there was simply no arm for it, so `a || b` was reported as an
            // unsupported operator. It lowers onto the CONCAT string function
            // the engine already implements.
            Expr::BinaryOp {
                left,
                op: BinaryOperator::StringConcat,
                right,
            } => {
                let left_reg = self.code_expr(left, ctx, None)?;
                let right_reg = self.code_expr(right, ctx, None)?;
                self.emit(
                    OpCode::StringFunc,
                    left_reg,
                    dest,
                    0,
                    Some(format!("CONCAT:{}", right_reg)),
                    &format!("r[{}] = r[{}] || r[{}]", dest, left_reg, right_reg),
                );
            }

            // Logical AND / OR, short-circuiting.
            //
            // The result register is initialized BEFORE the short-circuit
            // test. Registers persist across loop iterations, so a jump that
            // skips the initialization leaves this expression holding its
            // verdict from the PREVIOUS row -- which is exactly how AND came
            // to report true for a row failing both operands.
            Expr::BinaryOp {
                left,
                op: op @ (BinaryOperator::And | BinaryOperator::Or),
                right,
            } => {
                let is_and = matches!(op, BinaryOperator::And);
                // AND starts false and is set true only if both hold; OR
                // starts false and is set true as soon as either does.
                self.emit(
                    OpCode::Integer,
                    0,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = 0 ({:?} init)", dest, op),
                );
                let done = self.label();

                let left_reg = self.code_expr(left, ctx, None)?;
                if is_and {
                    self.emit_jump_to(OpCode::IfZ, left_reg, done, 0, None, "AND: left false");
                } else {
                    let check_right = self.label();
                    self.emit_jump_to(
                        OpCode::IfZ,
                        left_reg,
                        check_right,
                        0,
                        None,
                        "OR: left false, try right",
                    );
                    self.emit(OpCode::Integer, 1, dest, 0, None, "OR: left true");
                    self.emit_jump_to(OpCode::Goto, 0, done, 0, None, "");
                    self.resolve(check_right);
                }

                let right_reg = self.code_expr(right, ctx, None)?;
                self.emit_jump_to(OpCode::IfZ, right_reg, done, 0, None, "right false");
                self.emit(OpCode::Integer, 1, dest, 0, None, "both/either true");

                self.resolve(done);
            }

            // Arithmetic and comparison operators, compiled here rather than
            // delegated, so the name-resolution context propagates into the
            // operands. Delegating rebuilt a bare single-table context and
            // dropped any aggregate bindings, which is what made
            // `SUM(salary) + 1` report SUM as an unknown scalar function.
            Expr::BinaryOp { left, op, right }
                if matches!(
                    op,
                    BinaryOperator::Plus
                        | BinaryOperator::Minus
                        | BinaryOperator::Multiply
                        | BinaryOperator::Divide
                        | BinaryOperator::Modulo
                        | BinaryOperator::Gt
                        | BinaryOperator::Lt
                        | BinaryOperator::GtEq
                        | BinaryOperator::LtEq
                        | BinaryOperator::Eq
                        | BinaryOperator::NotEq
                ) =>
            {
                let left_reg = self.code_expr(left, ctx, None)?;
                let right_reg = self.code_expr(right, ctx, None)?;
                let opcode = match op {
                    BinaryOperator::Plus => OpCode::Add,
                    BinaryOperator::Minus => OpCode::Subtract,
                    BinaryOperator::Multiply => OpCode::Multiply,
                    BinaryOperator::Divide => OpCode::Divide,
                    BinaryOperator::Modulo => OpCode::Remainder,
                    BinaryOperator::Gt => OpCode::Gt,
                    BinaryOperator::Lt => OpCode::Lt,
                    BinaryOperator::GtEq => OpCode::Ge,
                    BinaryOperator::LtEq => OpCode::Le,
                    BinaryOperator::Eq => OpCode::Eq,
                    BinaryOperator::NotEq => OpCode::Ne,
                    _ => unreachable!("guarded above"),
                };
                self.emit(
                    opcode,
                    left_reg,
                    right_reg,
                    dest,
                    None,
                    &format!("r[{}] = r[{}] {:?} r[{}]", dest, left_reg, op, right_reg),
                );
            }

            // Logical negation, including NULL propagation. Previously
            // unsupported in any position.
            Expr::UnaryOp {
                op: UnaryOperator::Not,
                expr: inner,
            } => {
                let inner_reg = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::Not,
                    inner_reg,
                    dest,
                    0,
                    None,
                    &format!("r[{}] = NOT r[{}]", dest, inner_reg),
                );
            }

            // Function calls resolve their arguments in the CALLER's scope.
            //
            // Reaching them through the single-source fallback rebuilt a
            // context containing only the innermost table, so inside a
            // correlated subquery `UPPER(e.department)` silently resolved
            // `e.department` against the SUBQUERY table -- making both sides of
            // a comparison identical and matching every row.
            Expr::Function(func) => {
                self.compile_function(func, ctx, dest)?;
            }

            // TRIM / CEIL / FLOOR are their own Expr variants rather than
            // Function calls. They were previously handled only inside the
            // projection path, so they worked in a SELECT list and failed in
            // WHERE -- the same asymmetry SUBSTR had.
            Expr::Trim {
                expr: inner,
                trim_where: None,
                trim_what: None,
                ..
            } => {
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::StringFunc,
                    src,
                    dest,
                    0,
                    Some("TRIM".to_string()),
                    &format!("r[{}] = TRIM(r[{}])", dest, src),
                );
            }
            Expr::Ceil { expr: inner, .. } => {
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::MathFunc,
                    src,
                    dest,
                    -1,
                    Some("CEIL".to_string()),
                    &format!("r[{}] = CEIL(r[{}])", dest, src),
                );
            }
            Expr::Floor { expr: inner, .. } => {
                let src = self.code_expr(inner, ctx, None)?;
                self.emit(
                    OpCode::MathFunc,
                    src,
                    dest,
                    -1,
                    Some("FLOOR".to_string()),
                    &format!("r[{}] = FLOOR(r[{}])", dest, src),
                );
            }

            // Predicate-shaped expressions used as VALUES.
            //
            // These are compiled by the condition compiler, which is a third
            // parallel path. Routing them here means `SELECT x IS NULL`,
            // `SELECT name LIKE 'A%'` and `SELECT age BETWEEN 1 AND 2` work as
            // projected values, not just as filters -- SQL makes no
            // distinction between the two positions.
            Expr::IsNull(_)
            | Expr::IsNotNull(_)
            | Expr::Like { .. }
            | Expr::ILike { .. }
            | Expr::Between { .. }
            | Expr::InList { .. } => {
                let (table, cursor) = self.legacy_single_source(ctx, expr)?;
                let src = self.compile_where_condition(expr, table, cursor)?;
                if src != dest {
                    self.emit(
                        OpCode::Copy,
                        src,
                        dest,
                        0,
                        None,
                        &format!("r[{}] = r[{}]", dest, src),
                    );
                }
            }

            // Everything else still goes through the original operand
            // compiler. Arms migrate out of it into the match above as the
            // pipeline work proceeds; routing through here first means every
            // call site picks up the new capabilities immediately.
            other => {
                let (table, cursor) = self.legacy_single_source(ctx, other)?;
                self.compile_operand_legacy(other, table, cursor, dest)?;
            }
        }

        Ok(dest)
    }

    /// Emit whatever loads a resolved column into `dest`.
    fn emit_column_ref(&mut self, col: ColumnRef, dest: i64, label: &str) {
        match col {
            ColumnRef::Cursor { cursor, col } => self.emit(
                OpCode::Column,
                cursor,
                col as i64,
                dest,
                None,
                &format!("r[{}] = {} (column {})", dest, label, col),
            ),
            ColumnRef::Register(src) => {
                if src != dest {
                    self.emit(
                        OpCode::Copy,
                        src,
                        dest,
                        0,
                        None,
                        &format!("r[{}] = {} (r[{}])", dest, label, src),
                    );
                }
            }
        }
    }

    /// `code_expr` with the argument order the function compilers use.
    fn code_expr_into(
        &mut self,
        expr: &Expr,
        ctx: &NameCtx<'_>,
        target_reg: i64,
    ) -> SqawkResult<()> {
        self.code_expr(expr, ctx, Some(target_reg)).map(|_| ())
    }

    /// Compile `expr` as a boolean predicate, returning its register.
    #[allow(dead_code)] // wired up by the staged SELECT pipeline
    pub(crate) fn code_predicate(&mut self, expr: &Expr, ctx: &NameCtx<'_>) -> SqawkResult<i64> {
        let (table, cursor) = self.legacy_single_source(ctx, expr)?;
        self.compile_where_condition(expr, table, cursor)
    }

    /// Extract the single `(table, cursor)` pair the not-yet-migrated code
    /// still expects.
    ///
    /// With one FROM source this is trivial. With several, the arms that have
    /// not yet been migrated -- function calls above all -- still take a single
    /// `(table, cursor)`, so the source is inferred from the column references
    /// inside `expr`. A function almost always applies to columns of one
    /// table, and when it genuinely spans two this errors rather than
    /// resolving against an arbitrary one.
    fn legacy_single_source<'t>(
        &self,
        ctx: &NameCtx<'t>,
        expr: &Expr,
    ) -> SqawkResult<(&'t Table, usize)> {
        match ctx.srcs.len() {
            1 => return Ok((ctx.srcs[0].table, ctx.srcs[0].cursor as usize)),
            0 => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Expression requires a FROM clause: {:?}",
                    expr
                )))
            }
            _ => {}
        }

        let mut found: Option<usize> = None;
        let mut ambiguous = false;
        Self::for_each_column_ref(expr, &mut |qualifier, name| {
            let idx = match qualifier {
                Some(q) => ctx
                    .srcs
                    .iter()
                    .position(|s| s.refname == q.to_ascii_lowercase()),
                None => ctx.srcs.iter().position(|s| {
                    s.table
                        .column_metadata()
                        .iter()
                        .any(|c| c.name.eq_ignore_ascii_case(name))
                }),
            };
            if let Some(i) = idx {
                match found {
                    Some(prev) if prev != i => ambiguous = true,
                    _ => found = Some(i),
                }
            }
        });

        match (found, ambiguous) {
            (Some(i), false) => Ok((ctx.srcs[i].table, ctx.srcs[i].cursor as usize)),
            (_, true) => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Expression spans multiple tables: {:?}",
                expr
            ))),
            (None, _) => Ok((ctx.srcs[0].table, ctx.srcs[0].cursor as usize)),
        }
    }

    /// Visit every column reference in `expr` as `(qualifier, name)`.
    fn for_each_column_ref(expr: &Expr, f: &mut impl FnMut(Option<&str>, &str)) {
        match expr {
            Expr::Identifier(ident) => f(None, &ident.value),
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => f(
                Some(&parts[parts.len() - 2].value),
                &parts[parts.len() - 1].value,
            ),
            Expr::BinaryOp { left, right, .. } => {
                Self::for_each_column_ref(left, f);
                Self::for_each_column_ref(right, f);
            }
            Expr::UnaryOp { expr: inner, .. }
            | Expr::Nested(inner)
            | Expr::Cast { expr: inner, .. }
            | Expr::IsNull(inner)
            | Expr::IsNotNull(inner) => Self::for_each_column_ref(inner, f),
            Expr::Function(func) => {
                for arg in func_args(func) {
                    if let FunctionArg::Unnamed(FunctionArgExpr::Expr(e)) = arg {
                        Self::for_each_column_ref(e, f);
                    }
                }
            }
            _ => {}
        }
    }

    /// Shim preserving the old operand entry point.
    ///
    /// Every existing caller keeps working and gains the new capabilities
    /// (qualified names, case-insensitive resolution, `||`, `NOT`) for free.
    pub(crate) fn compile_where_operand(
        &mut self,
        expr: &Expr,
        table: &Table,
        cursor_idx: usize,
        target_reg: i64,
    ) -> SqawkResult<()> {
        let ctx = NameCtx::single(table, cursor_idx as i64);
        self.code_expr(expr, &ctx, Some(target_reg)).map(|_| ())
    }

    fn compile_operand_legacy(
        &mut self,
        expr: &Expr,
        table: &Table,
        cursor_idx: usize,
        target_reg: i64,
    ) -> SqawkResult<()> {
        match expr {
            Expr::Identifier(ident) => {
                // This is a column reference
                let column_name = &ident.value;
                let column_idx = self.find_column_index(table, column_name)?;

                self.emit(
                    OpCode::Column,
                    cursor_idx as i64,
                    column_idx as i64,
                    target_reg,
                    None,
                    &format!(
                        "r[{}] = column {} ({})",
                        target_reg, column_idx, column_name
                    ),
                );
            }
            Expr::Value(ValueWithSpan { value, .. }) => {
                // This is a literal value
                match value {
                    Value::Number(num, _) => {
                        if let Ok(int_val) = num.parse::<i64>() {
                            self.emit(
                                OpCode::Integer,
                                int_val,
                                target_reg,
                                0,
                                None,
                                &format!("r[{}] = {}", target_reg, int_val),
                            );
                        } else if let Ok(float_val) = num.parse::<f64>() {
                            // Store float as string for runtime conversion
                            self.emit(
                                OpCode::String,
                                0,
                                target_reg,
                                0,
                                Some(float_val.to_string()),
                                &format!("r[{}] = {} (float)", target_reg, float_val),
                            );
                        } else {
                            return Err(SqawkError::UnsupportedSqlFeature(format!(
                                "Invalid numeric literal in WHERE: {}",
                                num
                            )));
                        }
                    }
                    Value::SingleQuotedString(s) => {
                        self.emit(
                            OpCode::String,
                            0,
                            target_reg,
                            0,
                            Some(s.clone()),
                            &format!("r[{}] = '{}'", target_reg, s),
                        );
                    }
                    Value::Null => {
                        self.emit(
                            OpCode::Null,
                            0,
                            target_reg,
                            0,
                            None,
                            &format!("r[{}] = NULL", target_reg),
                        );
                    }
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported literal type in WHERE: {:?}",
                            value
                        )));
                    }
                }
            }
            Expr::Case {
                operand,
                conditions,
                else_result,
                ..
            } => {
                // Compile CASE expression, storing result directly in target_reg
                self.compile_case(
                    operand.as_deref(),
                    conditions,
                    else_result.as_deref(),
                    table,
                    cursor_idx,
                    Some(target_reg),
                )?;
            }
            Expr::BinaryOp { left, op, right } => {
                // Handle binary operations as operands (e.g., in CASE WHEN conditions or arithmetic)
                let left_reg = self.allocate_register();
                let right_reg = self.allocate_register();

                self.compile_where_operand(left, table, cursor_idx, left_reg)?;
                self.compile_where_operand(right, table, cursor_idx, right_reg)?;

                let opcode = match op {
                    // Comparison operators
                    BinaryOperator::Gt => OpCode::Gt,
                    BinaryOperator::Lt => OpCode::Lt,
                    BinaryOperator::GtEq => OpCode::Ge,
                    BinaryOperator::LtEq => OpCode::Le,
                    BinaryOperator::Eq => OpCode::Eq,
                    BinaryOperator::NotEq => OpCode::Ne,
                    // Arithmetic operators
                    BinaryOperator::Plus => OpCode::Add,
                    BinaryOperator::Minus => OpCode::Subtract,
                    BinaryOperator::Multiply => OpCode::Multiply,
                    BinaryOperator::Divide => OpCode::Divide,
                    BinaryOperator::Modulo => OpCode::Remainder,
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported binary operator in operand: {:?}",
                            op
                        )));
                    }
                };

                self.emit(
                    opcode,
                    left_reg,
                    right_reg,
                    target_reg,
                    None,
                    &format!(
                        "r[{}] = (r[{}] {:?} r[{}])",
                        target_reg, left_reg, op, right_reg
                    ),
                );
            }
            Expr::Cast {
                expr, data_type, ..
            } => {
                // Compile the expression to cast
                let src_reg = self.allocate_register();
                self.compile_where_operand(expr, table, cursor_idx, src_reg)?;

                // Get the target type name
                let type_name = self.sql_data_type_to_string(data_type);

                // Emit Cast instruction
                self.emit(
                    OpCode::Cast,
                    src_reg,
                    target_reg,
                    0,
                    Some(type_name.clone()),
                    &format!("r[{}] = CAST(r[{}] AS {})", target_reg, src_reg, type_name),
                );
            }
            Expr::Function(func) => {
                // Handle COALESCE and NULLIF functions
                self.compile_function(
                    func,
                    &NameCtx::single(table, cursor_idx as i64),
                    target_reg,
                )?;
            }
            Expr::Subquery(subquery) => {
                // Handle scalar subquery as an operand
                // Check for correlation first
                let outer_refs = self.detect_outer_references(subquery, table.name(), None);
                if outer_refs.is_empty() {
                    // Non-correlated: Execute subquery at compile time
                    let result_value = self.evaluate_scalar_subquery(subquery)?;
                    self.emit_value_literal(target_reg, &result_value)?;
                } else {
                    // Correlated: emit runtime execution bytecode
                    self.compile_correlated_scalar_subquery(
                        subquery,
                        table,
                        cursor_idx,
                        &outer_refs,
                        target_reg,
                    )?;
                }
            }
            Expr::Exists { subquery, negated } => {
                // Handle EXISTS (SELECT ...) as an operand
                // Check for correlation first
                let outer_refs = self.detect_outer_references(subquery, table.name(), None);
                if outer_refs.is_empty() {
                    // Non-correlated: Evaluate at compile time and emit 1 or 0
                    let exists_result = self.evaluate_exists_subquery(subquery, *negated)?;
                    self.emit(
                        OpCode::Integer,
                        if exists_result { 1 } else { 0 },
                        target_reg,
                        0,
                        None,
                        &format!(
                            "r[{}] = {} ({}EXISTS result)",
                            target_reg,
                            if exists_result { 1 } else { 0 },
                            if *negated { "NOT " } else { "" }
                        ),
                    );
                } else {
                    // Correlated: emit runtime execution bytecode
                    self.compile_correlated_exists_subquery(
                        subquery,
                        *negated,
                        table,
                        cursor_idx,
                        &outer_refs,
                        target_reg,
                    )?;
                }
            }
            Expr::InSubquery {
                expr: inner_expr,
                subquery,
                negated,
            } => {
                // Handle IN (SELECT ...) as an operand when combined with other conditions
                // We need to evaluate this at compile time for non-correlated subqueries
                let subquery_values = self.evaluate_in_subquery_values(subquery)?;
                if subquery_values.is_empty() {
                    // Empty subquery: IN is false, NOT IN is true
                    self.emit(
                        OpCode::Integer,
                        if *negated { 1 } else { 0 },
                        target_reg,
                        0,
                        None,
                        &format!(
                            "r[{}] = {} (empty IN subquery)",
                            target_reg,
                            if *negated { 1 } else { 0 }
                        ),
                    );
                } else {
                    // Get the expression value
                    let expr_reg = self.allocate_register();
                    self.compile_where_operand(inner_expr, table, cursor_idx, expr_reg)?;

                    // Initialize result
                    self.emit(
                        OpCode::Integer,
                        0,
                        target_reg,
                        0,
                        None,
                        &format!("r[{}] = 0 (IN subquery initial)", target_reg),
                    );

                    let temp_reg = self.allocate_register();
                    let mut jump_to_end_addrs = Vec::new();

                    for value in &subquery_values {
                        let item_reg = self.allocate_register();
                        self.emit_value_literal(item_reg, value)?;

                        self.emit(
                            OpCode::Eq,
                            expr_reg,
                            item_reg,
                            temp_reg,
                            None,
                            &format!("r[{}] = (r[{}] == r[{}])", temp_reg, expr_reg, item_reg),
                        );

                        let skip_set_addr = self.program.len();
                        self.emit(OpCode::IfZ, temp_reg, 0, 0, None, "if no match, skip");

                        self.emit(
                            OpCode::Integer,
                            1,
                            target_reg,
                            0,
                            None,
                            &format!("r[{}] = 1 (found)", target_reg),
                        );

                        jump_to_end_addrs.push(self.program.len());
                        self.emit(OpCode::Goto, 0, 0, 0, None, "skip to end");

                        let continue_addr = self.program.len();
                        if let Some(inst) = self.program.instructions.get_mut(skip_set_addr) {
                            inst.p2 = continue_addr as i64;
                        }
                    }

                    let end_label = self.program.len();
                    for addr in jump_to_end_addrs {
                        if let Some(inst) = self.program.instructions.get_mut(addr) {
                            inst.p2 = end_label as i64;
                        }
                    }

                    if *negated {
                        let zero_reg = self.allocate_register();
                        self.emit(
                            OpCode::Integer,
                            0,
                            zero_reg,
                            0,
                            None,
                            &format!("r[{}] = 0 for NOT IN", zero_reg),
                        );
                        self.emit(
                            OpCode::Eq,
                            target_reg,
                            zero_reg,
                            target_reg,
                            None,
                            &format!("r[{}] = (r[{}] == 0) for NOT IN", target_reg, target_reg),
                        );
                    }
                }
            }
            Expr::UnaryOp { op, expr: inner } => {
                match op {
                    UnaryOperator::Minus => {
                        // Handle unary minus using 0 - value (avoids Integer -1 special case)
                        let inner_reg = self.allocate_register();
                        self.compile_where_operand(inner, table, cursor_idx, inner_reg)?;
                        let zero_reg = self.allocate_register();
                        self.emit(
                            OpCode::Integer,
                            0,
                            zero_reg,
                            0,
                            None,
                            &format!("r[{}] = 0", zero_reg),
                        );
                        self.emit(
                            OpCode::Subtract,
                            zero_reg,
                            inner_reg,
                            target_reg,
                            None,
                            &format!("r[{}] = -r[{}]", target_reg, inner_reg),
                        );
                    }
                    UnaryOperator::Plus => {
                        // Unary plus is a no-op, just compile the inner expression
                        self.compile_where_operand(inner, table, cursor_idx, target_reg)?;
                    }
                    _ => {
                        return Err(SqawkError::UnsupportedSqlFeature(format!(
                            "Unsupported unary operator: {:?}",
                            op
                        )));
                    }
                }
            }
            // `SUBSTR(x, 1, 3)` parses as `Expr::Substring`, not as a
            // `Expr::Function`, so it needs an arm of its own here. (Older
            // sqlparser reserved this variant for the `SUBSTRING(x FROM 1 FOR
            // 3)` spelling and routed the comma form through Function.)
            Expr::Substring {
                expr: sub_expr,
                substring_from,
                substring_for,
                ..
            } => {
                self.compile_substring(
                    sub_expr,
                    substring_from.as_deref(),
                    substring_for.as_deref(),
                    table,
                    cursor_idx,
                    target_reg,
                )?;
            }
            _ => {
                return Err(SqawkError::UnsupportedSqlFeature(format!(
                    "Unsupported WHERE operand: {:?}",
                    expr
                )));
            }
        }

        Ok(())
    }

    /// Find column index by name
    pub(crate) fn find_column_index(&self, table: &Table, column_name: &str) -> SqawkResult<usize> {
        for (i, column) in table.column_metadata().iter().enumerate() {
            if column.name == column_name {
                return Ok(i);
            }
        }
        Err(SqawkError::ColumnNotFound(column_name.to_string()))
    }

    /// Convert a SQL DataType to a string representation for the VM
    fn sql_data_type_to_string(&self, data_type: &SqlDataType) -> String {
        match data_type {
            SqlDataType::Int(_)
            | SqlDataType::Integer(_)
            | SqlDataType::BigInt(_)
            | SqlDataType::SmallInt(_) => "INTEGER".to_string(),
            SqlDataType::Real | SqlDataType::Float(_) | SqlDataType::Double(_) => {
                "REAL".to_string()
            }
            SqlDataType::Text
            | SqlDataType::Varchar(_)
            | SqlDataType::Char(_)
            | SqlDataType::String(_) => "TEXT".to_string(),
            SqlDataType::Boolean => "BOOLEAN".to_string(),
            _ => format!("{:?}", data_type),
        }
    }

    /// Get a normalized table name from an ObjectName
    pub(crate) fn get_table_name(&self, name: &ObjectName) -> SqawkResult<String> {
        if name.0.is_empty() {
            return Err(SqawkError::InvalidSqlQuery("Empty table name".to_string()));
        }

        // Use the last part of the object name as the table name
        // (schemas and catalogs are ignored for now)
        Ok(object_name_last(name))
    }

    /// Whether a projection item needs expression compilation rather than a
    /// bare column load.
    ///
    /// Phrased as "not a plain column reference" rather than as an allowlist
    /// of computed forms. The allowlists this replaces named nine expression
    /// kinds and omitted CASE, CAST, IS NULL, LIKE, BETWEEN, IN and
    /// subqueries, so those fell through to the column-index path and were
    /// rejected with "Only column references supported in SELECT" -- even
    /// though the expression compiler handles them. An allowlist has to be
    /// updated every time an expression kind is added; this cannot drift.
    fn projection_needs_expr(projection: &[SelectItem]) -> bool {
        projection.iter().any(|item| {
            let expr = match item {
                SelectItem::UnnamedExpr(e) | SelectItem::ExprWithAlias { expr: e, .. } => e,
                _ => return false,
            };
            !matches!(expr, Expr::Identifier(_) | Expr::CompoundIdentifier(_))
        })
    }

    /// Emit post-processing ORDER BY / LIMIT / OFFSET over the result set.
    ///
    /// Used by the paths that produce rows without going through the
    /// cursor-based sorter -- GROUP BY, plain aggregates and joins. Those
    /// paths previously dropped ORDER BY and LIMIT on the floor: `query` was
    /// simply never passed to them, and for joins the code said so outright
    /// ("ORDER BY support for JOINs [...] isn't fully implemented. For now,
    /// compile the JOIN and skip ORDER BY").
    ///
    /// ORDER BY keys are matched against the SELECT list, since after
    /// aggregation the only columns that still exist are the projected ones.
    fn emit_result_post_processing(&mut self, select: &Select, query: &Query) -> SqawkResult<()> {
        // ORDER BY
        let order_by = query_order_by(query);
        if !order_by.is_empty() {
            let mut keys: Vec<String> = Vec::with_capacity(order_by.len());
            for ob in order_by {
                let out_columns = self.program.result_schema.columns.len();
                let pos = match Self::order_by_ordinal(&ob.expr, out_columns)? {
                    Some(idx) => idx,
                    None => Self::projection_position(&select.projection, &ob.expr)
                        .or_else(|| self.result_column_position(&ob.expr))
                        .ok_or_else(|| {
                            SqawkError::InvalidSqlQuery(format!(
                                "ORDER BY expression must appear in the SELECT list: {}",
                                ob.expr
                            ))
                        })?,
                };
                keys.push(format!(
                    "{}:{}",
                    pos,
                    if order_by_is_asc(ob) { "asc" } else { "desc" }
                ));
            }
            let spec = keys.join(",");
            self.emit(
                OpCode::SortResults,
                0,
                0,
                0,
                Some(spec.clone()),
                &format!("ORDER BY {}", spec),
            );
        }

        // LIMIT / OFFSET
        let limit = match query_limit(query) {
            Some(e) => Some(Self::const_i64(e, "LIMIT")?),
            None => None,
        };
        let offset = match query_offset(query) {
            Some(e) => Self::const_i64(e, "OFFSET")?,
            None => 0,
        };
        if limit.is_some() || offset > 0 {
            self.emit(
                OpCode::Limit,
                limit.unwrap_or(i64::MAX),
                offset,
                0,
                None,
                &format!("Limit {:?} offset {}", limit, offset),
            );
        }
        Ok(())
    }

    /// Position of `needle` within the SELECT list, if it appears there.
    ///
    /// Matches an alias by name, and otherwise compares the rendered
    /// expression, so `ORDER BY COUNT(*)` finds `COUNT(*)` in the projection
    /// and `ORDER BY department` finds a bare column.
    fn projection_position(projection: &[SelectItem], needle: &Expr) -> Option<usize> {
        let want = needle.to_string().to_ascii_lowercase();
        for (i, item) in projection.iter().enumerate() {
            let matches = match item {
                SelectItem::UnnamedExpr(e) => e.to_string().to_ascii_lowercase() == want,
                SelectItem::ExprWithAlias { expr, alias } => {
                    alias.value.to_ascii_lowercase() == want
                        || expr.to_string().to_ascii_lowercase() == want
                }
                _ => false,
            };
            if matches {
                return Some(i);
            }
        }
        None
    }

    /// A positional ORDER BY key (`ORDER BY 2`) as a zero-based output index.
    ///
    /// SQL numbers these from 1 against the SELECT list. Compiling such a key
    /// as an ordinary expression yields a CONSTANT, giving every row the same
    /// sort key and silently turning the sort into a no-op -- worse than the
    /// old code, which at least rejected the form.
    fn order_by_ordinal(expr: &Expr, out_columns: usize) -> SqawkResult<Option<usize>> {
        let n = match expr {
            Expr::Value(ValueWithSpan {
                value: Value::Number(n, _),
                ..
            }) => n,
            _ => return Ok(None),
        };
        let idx: usize = n.parse().map_err(|_| {
            SqawkError::InvalidSqlQuery(format!("Invalid ORDER BY position: {}", n))
        })?;
        if idx == 0 || idx > out_columns {
            return Err(SqawkError::InvalidSqlQuery(format!(
                "ORDER BY position {} is out of range (1..{})",
                idx, out_columns
            )));
        }
        Ok(Some(idx - 1))
    }

    /// Position of `expr` among the RESULT columns, by name.
    ///
    /// The projection-list search cannot see through a wildcard: `SELECT *`
    /// contributes one `SelectItem::Wildcard` while producing many output
    /// columns, so ordering a `SELECT *` join by any column found nothing and
    /// was rejected. The result schema is already built by the time
    /// post-processing is emitted and names every output column, including
    /// the expanded ones.
    ///
    /// Matches a qualified name exactly first, then falls back to the bare
    /// column name, so `ORDER BY name` finds an output column called `c.name`.
    fn result_column_position(&self, expr: &Expr) -> Option<usize> {
        let want = match expr {
            Expr::Identifier(ident) => ident.value.to_ascii_lowercase(),
            Expr::CompoundIdentifier(parts) if parts.len() >= 2 => format!(
                "{}.{}",
                parts[parts.len() - 2].value.to_ascii_lowercase(),
                parts[parts.len() - 1].value.to_ascii_lowercase()
            ),
            _ => return None,
        };

        let cols = &self.program.result_schema.columns;
        if let Some(i) = cols
            .iter()
            .position(|c| c.name.to_ascii_lowercase() == want)
        {
            return Some(i);
        }
        // Unqualified key against qualified output columns, or vice versa.
        let bare = want.rsplit('.').next().unwrap_or(&want).to_string();
        cols.iter().position(|c| {
            let n = c.name.to_ascii_lowercase();
            n == bare || n.rsplit('.').next().map(|x| x == bare).unwrap_or(false)
        })
    }

    /// Evaluate a LIMIT/OFFSET operand, which must be a constant.
    fn const_i64(expr: &Expr, what: &str) -> SqawkResult<i64> {
        match expr {
            Expr::Value(ValueWithSpan {
                value: Value::Number(n, _),
                ..
            }) => n
                .parse::<i64>()
                .map_err(|_| SqawkError::InvalidSqlQuery(format!("Invalid {} value: {}", what, n))),
            _ => Err(SqawkError::UnsupportedSqlFeature(format!(
                "Only constant {} supported",
                what
            ))),
        }
    }

    /// Resolve projection items to column indices
    fn resolve_projection(
        &self,
        projection: &[SelectItem],
        table: &Table,
    ) -> SqawkResult<Vec<usize>> {
        let mut columns = Vec::new();

        for item in projection {
            match item {
                // Multiple aliases for one item (`expr AS (a, b)`) is a
                // non-standard extension sqawk does not implement.
                SelectItem::ExprWithAliases { .. } => {
                    return Err(SqawkError::UnsupportedSqlFeature(
                        "Multiple column aliases are not supported".into(),
                    ))
                }
                SelectItem::Wildcard(_) => {
                    // SELECT * - include all columns
                    for i in 0..table.column_count() {
                        columns.push(i);
                    }
                }
                SelectItem::UnnamedExpr(expr) => {
                    let col_idx = self.resolve_column_expr(expr, table)?;
                    columns.push(col_idx);
                }
                SelectItem::ExprWithAlias { expr, .. } => {
                    let col_idx = self.resolve_column_expr(expr, table)?;
                    columns.push(col_idx);
                }
                SelectItem::QualifiedWildcard(name, _) => {
                    // table.* - for now just include all columns
                    let _ = name; // Ignore table qualifier for single-table queries
                    for i in 0..table.column_count() {
                        columns.push(i);
                    }
                }
            }
        }

        if columns.is_empty() {
            // Default to all columns
            Ok((0..table.column_count()).collect())
        } else {
            Ok(columns)
        }
    }

    pub(crate) fn resolve_column_expr(&self, expr: &Expr, table: &Table) -> SqawkResult<usize> {
        match expr {
            Expr::Identifier(ident) => {
                let col_name = ident.value.to_lowercase();
                table
                    .column_index(&col_name)
                    .ok_or(SqawkError::ColumnNotFound(col_name))
            }
            Expr::CompoundIdentifier(parts) => {
                let col_name = parts
                    .last()
                    .map(|p| p.value.to_lowercase())
                    .unwrap_or_default();
                table
                    .column_index(&col_name)
                    .ok_or(SqawkError::ColumnNotFound(col_name))
            }
            _ => Err(SqawkError::UnsupportedSqlFeature(
                "Only column references supported in SELECT".into(),
            )),
        }
    }

    pub(crate) fn get_column_name_from_expr(&self, expr: &Expr) -> String {
        match expr {
            Expr::Identifier(ident) => ident.value.clone(),
            Expr::CompoundIdentifier(parts) => {
                parts.last().map(|p| p.value.clone()).unwrap_or_default()
            }
            Expr::Function(func) => {
                // For aggregate functions, return just the function name (e.g., "COUNT" not "COUNT(*)")
                // For other functions, include arguments for clarity
                let func_name = func.name.to_string().to_uppercase();
                if matches!(func_name.as_str(), "COUNT" | "SUM" | "AVG" | "MIN" | "MAX") {
                    func_name
                } else if let Some(FunctionArg::Unnamed(FunctionArgExpr::Wildcard)) =
                    func_args(func).first()
                {
                    format!("{}(*)", func_name)
                } else if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg_expr))) =
                    func_args(func).first()
                {
                    format!(
                        "{}({})",
                        func_name,
                        self.get_column_name_from_expr(arg_expr)
                    )
                } else {
                    format!("{}()", func_name)
                }
            }
            // SUBSTR/SUBSTRING is its own Expr variant rather than a Function,
            // so it needs an arm here to keep the descriptive column name
            // (`SUBSTR(name)`) instead of falling through to `expr`.
            Expr::Substring { expr, .. } => {
                format!("SUBSTR({})", self.get_column_name_from_expr(expr))
            }
            _ => "expr".to_string(),
        }
    }

    /// Build a ResultSchema from a projection and table
    ///
    /// This creates a proper schema with column names and types for the result set.
    pub(crate) fn build_result_schema(
        &self,
        projection: &[SelectItem],
        table: &Table,
    ) -> ResultSchema {
        let mut schema = ResultSchema::new();
        let col_metadata = table.column_metadata();

        for item in projection {
            match item {
                // Multiple aliases for one item (`expr AS (a, b)`) is a
                // non-standard extension sqawk does not implement. This
                // function cannot fail; the compile path rejects the item.
                SelectItem::ExprWithAliases { .. } => {}
                SelectItem::Wildcard(_) | SelectItem::QualifiedWildcard(_, _) => {
                    // Add all columns from the table with their types
                    for meta in col_metadata {
                        schema.add_column(meta.name.clone(), meta.data_type);
                    }
                }
                SelectItem::UnnamedExpr(expr) => {
                    let name = self.get_column_name_from_expr(expr);
                    let data_type = self.infer_expr_type(expr, table);
                    schema.add_column(name, data_type);
                }
                SelectItem::ExprWithAlias { expr, alias } => {
                    let data_type = self.infer_expr_type(expr, table);
                    schema.add_column(alias.value.clone(), data_type);
                }
            }
        }
        schema
    }

    /// Infer the data type of an expression
    pub(crate) fn infer_expr_type(&self, expr: &Expr, table: &Table) -> DataType {
        match expr {
            Expr::Identifier(ident) => {
                // Look up the column type in the table
                let col_meta = table.column_metadata();
                for meta in col_meta {
                    if meta.name.eq_ignore_ascii_case(&ident.value) {
                        return meta.data_type;
                    }
                }
                DataType::Text // Default to text if not found
            }
            Expr::CompoundIdentifier(parts) => {
                // For table.column references, use the column name
                if let Some(col_name) = parts.last() {
                    let col_meta = table.column_metadata();
                    for meta in col_meta {
                        if meta.name.eq_ignore_ascii_case(&col_name.value) {
                            return meta.data_type;
                        }
                    }
                }
                DataType::Text
            }
            Expr::Function(func) => {
                let func_name = func.name.to_string().to_uppercase();
                match func_name.as_str() {
                    "COUNT" => DataType::Integer,
                    "SUM" | "AVG" => {
                        // SUM/AVG preserves numeric type, defaults to Float for AVG
                        if func_name == "AVG" {
                            DataType::Float
                        } else {
                            // Try to infer from argument
                            if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                                func_args(func).first()
                            {
                                let arg_type = self.infer_expr_type(arg, table);
                                if matches!(arg_type, DataType::Integer) {
                                    return DataType::Integer;
                                }
                            }
                            DataType::Float
                        }
                    }
                    "MIN" | "MAX" => {
                        // MIN/MAX preserves the type of the argument
                        if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                            func_args(func).first()
                        {
                            return self.infer_expr_type(arg, table);
                        }
                        DataType::Text
                    }
                    "UPPER" | "LOWER" | "TRIM" | "LTRIM" | "RTRIM" | "SUBSTR" | "REPLACE" => {
                        DataType::Text
                    }
                    "COALESCE" => {
                        // COALESCE returns the type of its first non-null argument
                        if let Some(FunctionArg::Unnamed(FunctionArgExpr::Expr(arg))) =
                            func_args(func).first()
                        {
                            return self.infer_expr_type(arg, table);
                        }
                        DataType::Text
                    }
                    _ => DataType::Text,
                }
            }
            Expr::Value(ValueWithSpan { value: val, .. }) => {
                match val {
                    Value::Number(_, _) => DataType::Integer, // Could be Float, but Integer is common
                    Value::SingleQuotedString(_) | Value::DoubleQuotedString(_) => DataType::Text,
                    Value::Boolean(_) => DataType::Boolean,
                    Value::Null => DataType::Text, // NULL doesn't have a type, default to Text
                    _ => DataType::Text,
                }
            }
            Expr::BinaryOp { left, op, right: _ } => {
                // Arithmetic ops return numeric, comparisons return boolean
                match op {
                    BinaryOperator::Plus
                    | BinaryOperator::Minus
                    | BinaryOperator::Multiply
                    | BinaryOperator::Divide
                    | BinaryOperator::Modulo => self.infer_expr_type(left, table),
                    BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::And
                    | BinaryOperator::Or => DataType::Boolean,
                    BinaryOperator::StringConcat => DataType::Text,
                    _ => DataType::Text,
                }
            }
            Expr::Case {
                conditions,
                else_result,
                ..
            } => {
                // CASE returns the type of its first result
                if let Some(first) = conditions.first() {
                    return self.infer_expr_type(&first.result, table);
                }
                if let Some(else_expr) = else_result {
                    return self.infer_expr_type(else_expr, table);
                }
                DataType::Text
            }
            Expr::Cast { data_type, .. } => {
                // CAST returns the target type
                match data_type {
                    SqlDataType::Int(_)
                    | SqlDataType::Integer(_)
                    | SqlDataType::BigInt(_)
                    | SqlDataType::SmallInt(_) => DataType::Integer,
                    SqlDataType::Real | SqlDataType::Float(_) | SqlDataType::Double(_) => {
                        DataType::Float
                    }
                    SqlDataType::Boolean => DataType::Boolean,
                    _ => DataType::Text,
                }
            }
            _ => DataType::Text, // Default
        }
    }

    /// Check if a SELECT projection contains aggregate functions
    fn has_aggregates(&self, projection: &[SelectItem]) -> bool {
        for item in projection {
            match item {
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. }
                    if self.is_aggregate_expr(expr) =>
                {
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    /// Whether `expr` is directly an aggregate call.
    ///
    /// A free function so the grouped-projection planner can use it without a
    /// compiler borrow.
    pub(crate) fn is_aggregate_call(expr: &Expr) -> bool {
        match expr {
            Expr::Function(func) if func.over.is_none() => {
                let name = func.name.to_string().to_uppercase();
                matches!(name.as_str(), "COUNT" | "SUM" | "AVG" | "MIN" | "MAX")
            }
            _ => false,
        }
    }

    /// Check if an expression is or CONTAINS an aggregate function.
    ///
    /// Recursive: this used to match only a top-level call, so
    /// `SELECT SUM(salary) + 1` was not recognised as an aggregate query and
    /// took the plain table-scan path, where SUM is not a known scalar
    /// function.
    fn is_aggregate_expr(&self, expr: &Expr) -> bool {
        if Self::is_aggregate_call(expr) {
            return true;
        }
        match expr {
            Expr::BinaryOp { left, right, .. } => {
                self.is_aggregate_expr(left) || self.is_aggregate_expr(right)
            }
            Expr::UnaryOp { expr: inner, .. }
            | Expr::Nested(inner)
            | Expr::Cast { expr: inner, .. } => self.is_aggregate_expr(inner),
            _ => false,
        }
    }

    /// Check if the projection contains any window functions
    fn has_window_functions(&self, projection: &[SelectItem]) -> bool {
        for item in projection {
            match item {
                SelectItem::UnnamedExpr(expr) | SelectItem::ExprWithAlias { expr, .. }
                    if self.is_window_expr(expr) =>
                {
                    return true;
                }
                _ => {}
            }
        }
        false
    }

    /// Check if an expression is a window function (has OVER clause)
    fn is_window_expr(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Function(func) => func.over.is_some(),
            _ => false,
        }
    }

    /// Get the window function type code
    pub(crate) fn get_window_func_type(&self, name: &str) -> i64 {
        match name.to_uppercase().as_str() {
            "ROW_NUMBER" => 0,
            "RANK" => 1,
            "DENSE_RANK" => 2,
            "LAG" => 3,
            "LEAD" => 4,
            "SUM" => 5,
            "AVG" => 6,
            "COUNT" => 7,
            "MIN" => 8,
            "MAX" => 9,
            _ => 0,
        }
    }
}
